window.GOFORGE_GYM_THEORY=[
  {"id":"dedupe","category":"Go Core","section":"Срезы и map: дедупликация","sources":["https://github.com/yakomisar/golang-questions#slices","https://github.com/yakomisar/golang-questions#maps","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"practice":{"button":"Решить задачу UniqueUsers","code":"recipients := UniqueUsers(recipientIDs)\nreturn notifier.Notify(ctx, recipients, eventID)"},"theory":[
    ["Зачем это нужно в работе","Календарный сервис собирает получателей уведомления о встрече. Пользователь 101 приглашён напрямую и входит в приглашённую группу. Если отправить уведомление на каждый ID в объединённом списке, он получит два одинаковых уведомления.",{"animation":"./media/dedupe-recipients.gif","still":"./media/dedupe-recipients-still.png","height":260,"alt":"Два списка дают пять записей. После дедупликации остаются три получателя.","practice":"Прими объединённый срез ID. Верни каждый ID один раз, в порядке первого появления.","code":"ids := []string{\"101\", \"202\", \"101\", \"303\", \"202\"}\nrecipients := UniqueUsers(ids) // [\"101\", \"202\", \"303\"]","production":"Вызывай UniqueUsers между объединением списков и отправкой уведомления. Так каждый ID попадёт в список получателей один раз в рамках этой отправки."}],
    ["Как устроен срез","Срез хранит ссылку на участок массива, длину len и ёмкость cap. При передаче в функцию копируется описание среза, а данные могут оставаться общими. Если ёмкости хватает, append пишет в тот же массив. Если места не хватает, append выделяет новый массив.",{"animation":"./media/dedupe-slice.gif","still":"./media/dedupe-slice-still.png","height":260,"alt":"После записи через ids[:2] значение меняется и в ids, поскольку срезы разделяют массив.","practice":"Создай отдельный result с длиной 0 и ёмкостью len(ids). Добавляй туда новые ID, чтобы сохранить входной список для вызывающего кода.","code":"result := make([]string, 0, len(ids))\nresult = append(result, \"101\") // len(result) == 1","production":"При фильтрации участников календарного события исходный список может понадобиться для другой части обработки. Отдельный результирующий срез позволяет передать отфильтрованных участников дальше и сохранить исходные данные."}],
    ["Почему здесь map","map хранит уже встреченные ID. В выражении _, ok := seen[id] флаг ok показывает, существует ли ключ. Значение struct{}{} пустое, потому что нам важен сам факт наличия ключа. Поиск в map в среднем занимает O(1).",{"animation":"./media/dedupe-map.gif","still":"./media/dedupe-map-still.png","height":260,"alt":"Первая проверка ключа 101 даёт false. После записи того же ключа проверка даёт true.","practice":"Проверяй seen на каждой итерации. Если ключ уже есть, переходи к следующему ID.","code":"if _, ok := seen[id]; ok {\n    continue\n}\nseen[id] = struct{}{}","production":"Перед пакетным запросом профилей можно тем же способом убрать повторяющиеся userID. Например, один профиль нужен сразу для нескольких записей в ленте, а запрашивать его достаточно один раз."}],
    ["Построение решения","Проходим по ids слева направо. Для нового ID записываем ключ в seen и добавляем ID в result. Повтор пропускаем. Порядок результата задаёт обход входного среза. Порядок обхода map в Go не определён.",{"animation":"./media/dedupe.gif","still":"./media/dedupe-still.png","height":360,"alt":"На повторном ID 101 ключ уже есть в seen, поэтому результат остаётся [101, 202].","practice":"Проверь шаг с повторной 101 вручную. К этому моменту в result уже лежат 101 и 202. После проверки seen содержимое result должно остаться прежним.","code":"for _, id := range ids {\n    // Проверь seen[id]. Для нового ID заполни seen и result.\n}","production":"Дедупликацию получателей удобно держать рядом с отправкой, когда все списки уже собраны. При повторной обработке события функция получит новый seen. Для защиты от повторной доставки между запусками нужен отдельный механизм идемпотентности."}],
    ["Под капотом и интервью","Если искать каждый ID во всём уже собранном результате, при n разных ID число сравнений растёт как O(n²). С map один обход занимает в среднем O(n). В map хранится по ключу на уникальный ID. В этой реализации result заранее резервирует ёмкость под весь вход.",{"animation":"./media/dedupe-complexity.gif","still":"./media/dedupe-complexity-still.png","height":260,"alt":"На пяти различных ID линейный поиск делает десять сравнений, а вариант с map выполняет пять проверок ключа.","practice":"На собеседовании объясни, почему нужны две структуры: seen отвечает на вопрос «встречался ли ID», а result хранит ID в нужном порядке.","code":"seen := make(map[string]struct{}, len(ids))\nresult := make([]string, 0, len(ids))","production":"При рассылке по большой группе предварительное выделение памяти сокращает рост среза. Если список очень большой и почти весь состоит из повторов, сравни объём аллокаций через go test -bench . -benchmem."}],
    ["Что попробовать руками","Тест на повторы проверяет состав и порядок результата. Тест на пустой вход проверяет длину результата. Ещё один тест может проверить, что содержимое исходного среза не изменилось.",{"animation":"./media/dedupe-tests.gif","still":"./media/dedupe-tests-still.png","height":260,"alt":"Три проверки: порядок первого появления, пустой вход и сохранение исходного среза.","practice":"Напиши UniqueUsers в песочнице и запусти Go-тесты. Затем вручную проверь вход, где все ID одинаковые, и сравни исходный срез до и после вызова.","code":"got := UniqueUsers([]string{\"202\", \"101\", \"202\"})\n// want: []string{\"202\", \"101\"}","production":"В тесте обработчика уведомлений подставь тестовый notifier и проверь список, который получил его метод Notify. Так тест проверит применение дедупликации перед отправкой."}]
  ]},
  {"id":"filter","category":"Go Core","section":"Срезы: фильтрация и память","sources":["https://github.com/yakomisar/golang-questions#slices","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Задача из backend","Сервис возвращает список событий, а клиенту нужны только активные. Нужно выбрать элементы по условию и решить, допустимо ли менять исходный срез. Это отличается от учебного примера не алгоритмом, а требованием к контракту функции.",{"animation":"./media/filter-1.gif","still":"./media/filter-1-still.png","height":286,"alt":"active → cancelled → active. Оставляем первое и третье события.","practice":"Проверяй статус в цикле и добавляй только active.","code":"if ev.Status == \"active\" { out = append(out, ev) }","production":"Фильтруй отменённые встречи при формировании списка активных."}],
    ["Почему append важнее, чем кажется","Обычно результат собирают через make([]Event,0,len(events)) и append. Длина исходного среза при этом не изменяется. Но если взять result := events[:0], получишь дешёвую фильтрацию на том же backing array — её запись может перезаписать исходные элементы, даже если позже возвращается другой slice.",{"animation":"./media/filter-2.gif","still":"./media/filter-2-still.png","height":286,"alt":"out: len=0, cap=3. append: len=1, cap=3.","practice":"Начинай с пустого результата с запасом ёмкости.","code":"out := make([]Event, 0, len(events))","production":"При обработке небольших пачек это сокращает рост массива."}],
    ["Скрытые ссылки","Срезы и структуры могут содержать ссылочные поля: pointers, maps, slices. Копирование структуры через присваивание копирует поле-slice как описатель; вложенный массив остаётся общим. Если вызывающий ожидает глубокую независимость, требуется отдельное копирование соответствующих данных.",{"animation":"./media/filter-3.gif","still":"./media/filter-3-still.png","height":286,"alt":"out := events[:0] делит массив. append перезаписывает элементы events.","practice":"Создавай отдельный срез. Поля Event в задаче — строки.","code":"out := make([]Event, 0, len(events))","production":"Если модель содержит map или указатели, для независимого редактирования этих полей нужна отдельная копия."}],
    ["Как отлаживать","Сначала сформулируй инвариант: результат содержит только active в исходном порядке. Затем проверь, что вход не меняется после вызова. Добавь случай с nil, пустым списком, всеми отменёнными событиями. Даже если тесты зелёные, проверь, не удерживает ли маленький subslice большой буфер.",{"animation":"./media/filter-4.gif","still":"./media/filter-4-still.png","height":286,"alt":"вход: A active, B cancelled. выход: A; вход по-прежнему A, B.","practice":"Проверь состав результата и исходные значения.","code":"got := Active(events)","production":"Тест фильтра защищает обработчики, которые используют один список в нескольких местах."}],
    ["Как отвечать на интервью","Сравни массив, срез, копирование, cap, append, aliasing. Уточни, что спецификация Go гарантирует семантику, а точный коэффициент роста capacity — деталь runtime. Покажи пример, где два среза изменяют общий элемент.",{"animation":"./media/filter-5.gif","still":"./media/filter-5-still.png","height":286,"alt":"идём по events слева направо. out сохраняет порядок подходящих событий.","practice":"Объясни один проход и выделение отдельного результата.","code":"for _, ev := range events { /* проверка статуса */ }","production":"Если список сразу читается из БД, фильтр WHERE может уменьшить объём переданных данных."}],
    ["Практика","Реализуй Active двумя способами — с новым backing array и in-place. Напиши тест, который доказывает различие. Объясни, какую реализацию выберешь в публичном API, где важна неизменность входных данных.",{"animation":"./media/filter-6.gif","still":"./media/filter-6-still.png","height":286,"alt":"только cancelled. результат длины 0.","practice":"Проверь пустой вход и случай без совпадений.","code":"if len(Active(events)) != 0 { t.Fatal(\"expected no events\") }","production":"Код, который сериализует ответ, должен соблюдать контракт API для пустого списка."}]
  ]},
  {"id":"errors","category":"Go Core","section":"Ошибки: цепочка причин","sources":["https://github.com/goavengers/go-interview/tree/master/docs/golang","https://github.com/yakomisar/golang-questions"],"theory":[
    ["Что такое ошибка в Go","В Go ошибка обычно является последним возвращаемым значением, а не исключением, которое автоматически прерывает выполнение. Интерфейс error содержит метод Error() string. Вызывающий код обязан решить, что делать: повторить операцию, вернуть ошибку клиенту, продолжить с частичным результатом или остановиться.",{"animation":"./media/errors-1.gif","still":"./media/errors-1-still.png","height":286,"alt":"repo вернул ошибку. service передаёт её с описанием операции.","practice":"Пустую ошибку возвращай как nil.","code":"if err == nil { return nil }","production":"Сервис завершает успешное чтение обычным результатом."}],
    ["Почему нельзя терять причину","Слой repository может вернуть ErrNotFound, service добавит контекст «load event», а handler должен преобразовать известную причину в код NotFound. Если создать fmt.Errorf(\"%v\",err), текст сохранится, но связь с исходной ошибкой не будет доступна errors.Is. Для цепочки нужен %w.",{"animation":"./media/errors-2.gif","still":"./media/errors-2-still.png","height":286,"alt":"err → текст через %v. err → причина в цепочке через %w.","practice":"Используй %w, чтобы сохранить исходную ошибку.","code":"return fmt.Errorf(\"load event: %w\", err)","production":"Логи показывают операцию, на которой возникла ошибка чтения."}],
    ["errors.Is и errors.As","errors.Is проверяет соответствие целевой ошибке с учётом цепочки Unwrap. errors.As ищет в цепочке ошибку подходящего типа. Они решают разные задачи: одна — классификация по sentinel error, другая — извлечение типизированной ошибки с полями.",{"animation":"./media/errors-3.gif","still":"./media/errors-3-still.png","height":286,"alt":"wrapped → cause. errors.Is находит исходную причину.","practice":"Проверь результат обёртки через errors.Is; для извлечения типа используй errors.As.","code":"ok := errors.Is(WithContext(cause), cause)","production":"Обработчик может распознать ErrEventNotFound после нескольких обёрток."}],
    ["Граница транспортного слоя","В сервисе Go не стоит смешивать бизнес-логику и коды HTTP/gRPC без необходимости. Сервис возвращает доменную причину, handler маппит её в статус. Не нужно логировать каждую ошибку на каждом слое: это создаёт дублирующиеся записи и шум в observability.",{"animation":"./media/errors-4.gif","still":"./media/errors-4-still.png","height":286,"alt":"ошибка repository → service. handler → публичный статус.","practice":"Добавляй контекст операции, а перевод в транспортный статус оставь вызывающему слою.","code":"err = WithContext(err)","production":"Для ожидаемой ошибки handler вернёт NotFound, для неизвестной — общий Internal."}],
    ["Panic отличается от error","Ошибки вроде некорректного запроса, отсутствующей строки или недоступной БД ожидаемы и должны возвращаться как error. panic уместен для нарушенных инвариантов или фатальных ошибок программирования, но не как штатная обработка плохого JSON.",{"animation":"./media/errors-5.gif","still":"./media/errors-5-still.png","height":286,"alt":"ожидаемая ошибка чтения. return error → обычная обработка.","practice":"Возвращай ошибку через контракт функции.","code":"return fmt.Errorf(\"load event: %w\", err)","production":"Паники на границе сервера обычно обрабатывают отдельно через recovery middleware."}],
    ["Практика и интервью","Напиши WithContext с nil-safe логикой, затем тест с errors.Is. Добавь собственный тип ошибки и проверь errors.As. На собеседовании объясни, в каком месте ты переводишь доменную ошибку в codes.NotFound.",{"animation":"./media/errors-6.gif","still":"./media/errors-6-still.png","height":286,"alt":"nil → nil. cause → errors.Is == true.","practice":"Проверь оба пути и наличие контекста в сообщении.","code":"if !errors.Is(WithContext(cause), cause) { t.Fatal(\"cause lost\") }","production":"Регрессионный тест ловит случайную замену %w на %v."}]
  ]},
  {"id":"json","category":"Backend","section":"HTTP и JSON: обработка запроса","sources":["https://github.com/goavengers/go-interview/tree/master/docs/common","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Путь запроса","HTTP клиент отправляет байты: метод, URL, заголовки и тело. Handler читает тело и преобразует JSON в структуру Go. Это не «сразу готовая структура»: на каждом шаге возможна ошибка ввода, превышение лимита или неверные типы полей.",{"animation":"./media/json-1.gif","still":"./media/json-1-still.png","height":286,"alt":"HTTP body → io.Reader. Decoder → CreateEventRequest.","practice":"Принимай io.Reader, чтобы декодировать и тело HTTP, и тестовую строку.","code":"req, err := DecodeEvent(r.Body)","production":"В handler передай тело запроса после ограничения размера."}],
    ["Структура и теги","Теги json задают имена полей в формате обмена. Экспортируемые поля (с заглавной буквы) доступны encoding/json. Отсутствующее поле и zero value не всегда различимы без указателя или отдельного типа; решение зависит от контракта API.",{"animation":"./media/json-2.gif","still":"./media/json-2-still.png","height":286,"alt":"JSON: owner_id. Go: OwnerID.","practice":"Сопоставь имена полей через JSON-теги.","code":"OwnerID string `json:\"owner_id\"`","production":"Теги сохраняют публичный формат API при идиоматичных именах Go."}],
    ["Decoder и ошибки","json.NewDecoder(r).Decode(&req) читает одно JSON-значение из io.Reader. Ошибку синтаксиса нужно обработать. Если API ожидает строго один объект, после первого Decode следует проверить отсутствие второго значения, например вторым Decode с ожиданием io.EOF.",{"animation":"./media/json-3.gif","still":"./media/json-3-still.png","height":286,"alt":"полный JSON → структура. обрезанный JSON → ошибка Decode.","practice":"Проверь ошибку декодирования перед проверкой полей.","code":"if err := json.NewDecoder(r).Decode(&req); err != nil { return req, err }","production":"Handler может вернуть HTTP 400 при синтаксической ошибке тела."}],
    ["Безопасность и валидация","Ограничивай размер входных данных. Для http.Handler можно применить http.MaxBytesReader. Валидация «title не пустой» относится к бизнес-правилам и должна проверяться отдельно. Запрет неизвестных полей возможен через DisallowUnknownFields, если это соответствует договорённостям о совместимости.",{"animation":"./media/json-4.gif","still":"./media/json-4-still.png","height":286,"alt":"JSON корректен: title=\"  \". TrimSpace → пустой заголовок.","practice":"Отдельно проверь обязательный title.","code":"if strings.TrimSpace(req.Title) == \"\" { return req, errors.New(\"title is required\") }","production":"HTTP-слой может ограничить тело, а правила обязательности полей удобно проверять после разбора."}],
    ["Связь с gRPC","gRPC использует Protobuf и другой транспортный контракт, но принцип остаётся прежним: handler проверяет входные данные и преобразует их в типы доменной логики. Контекст запроса, deadline и user identity нельзя терять.",{"animation":"./media/json-5.gif","still":"./media/json-5-still.png","height":286,"alt":"JSON → DTO. protobuf → DTO → правила.","practice":"Проверяй заголовок после получения типизированного значения.","code":"title := strings.TrimSpace(req.Title)","production":"HTTP и gRPC могут применять одинаковые доменные правила к разным входным форматам."}],
    ["Практика","Напиши DecodeEvent, проверь пустой title, неверный JSON, неизвестные поля и второй объект. На собеседовании объясни разницу между декодированием, валидацией и авторизацией — это три разные обязанности.",{"animation":"./media/json-6.gif","still":"./media/json-6-still.png","height":286,"alt":"валидный JSON → успех. битый JSON и пустой title → ошибки.","practice":"Тестируй через strings.NewReader.","code":"_, err := DecodeEvent(strings.NewReader(`{\"title\":\" \"}`))","production":"Тест handler дополняет проверку декодера статусом и телом ответа."}]
  ]},
  {"id":"pagination","category":"Backend","section":"Пагинация: границы и курсоры","sources":["https://github.com/goavengers/go-interview/tree/master/docs/cache_and_db","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Зачем нужна пагинация","Возвращать миллион событий одним ответом дорого по памяти, сети и времени. Пагинация ограничивает объём данных и позволяет клиенту получать следующий фрагмент. Но последовательность страниц должна иметь определённый порядок.",{"animation":"./media/pagination-1.gif","still":"./media/pagination-1-still.png","height":286,"alt":"все ID: A B C D E. страница из двух: A B.","practice":"Принимай offset и limit как параметры выдачи.","code":"first := Page(ids, 0, 2)","production":"Список чатов может отображать небольшие страницы вместо всей истории."}],
    ["Offset и limit","Для среза offset определяет начальную позицию, limit — максимальное число элементов. Нельзя обращаться к s[start:end] без проверки границ. Учитывай отрицательные значения, offset после конца и переполнение при сумме offset+limit.",{"animation":"./media/pagination-2.gif","still":"./media/pagination-2-still.png","height":286,"alt":"offset=2, limit=2. ids[2:4] → C D.","practice":"Сначала проверь offset и limit, затем ограничь правую границу.","code":"if limit < len(ids)-offset { end = offset + limit }","production":"Для HTTP API проверь параметры ещё до обращения к хранилищу."}],
    ["Что происходит в SQL","LIMIT/OFFSET на больших таблицах может требовать сканирования или пропуска большого числа строк; без ORDER BY стабильного порядка нет. При параллельных изменениях строк offset pagination может пропускать или повторять записи.",{"animation":"./media/pagination-3.gif","still":"./media/pagination-3-still.png","height":286,"alt":"ORDER BY задаёт порядок. OFFSET пропускает строки.","practice":"В учебной функции срез уже упорядочен, поэтому offset — индекс.","code":"part := ids[offset:end]","production":"SQL с большим OFFSET может читать и отбрасывать много строк."}],
    ["Cursor pagination","Cursor обычно содержит значения последней сортировочной позиции. Следующая страница использует условие «после этого ключа». Сортировка должна быть стабильной, при одинаковых timestamp нужен tie-breaker вроде ID. Курсор нельзя слепо принимать без валидации.",{"animation":"./media/pagination-4.gif","still":"./media/pagination-4-still.png","height":286,"alt":"первая страница: A B. следующая: записи после B.","practice":"Сравни индекс offset с позицией последней записи B.","code":"next := Page(ids, offset+len(current), limit)","production":"Для растущей таблицы событий часто используют курсор из ключей сортировки."}],
    ["Токен и контракт","Page token обычно должен быть непрозрачным для клиента и содержать достаточно информации для продолжения. Он может быть подписан от подмены и привязан к фильтру, если это требуется API. Page size нужно ограничивать серверной максимальной величиной.",{"animation":"./media/pagination-5.gif","still":"./media/pagination-5-still.png","height":286,"alt":"клиент передаёт позицию. сервер проверяет формат и предел.","practice":"В Page некорректный offset или limit даёт пустой результат.","code":"if offset < 0 || limit <= 0 || offset >= len(ids) { return []string{} }","production":"На API-границе токен связывают с сортировкой и фильтрами запроса."}],
    ["Практика","Реализуй Page для среза; затем спроектируй ListEvents с page_size/page_token и order_by. Объясни, как поведёт себя выдача, если в базе появились новые события между запросами страниц.",{"animation":"./media/pagination-6.gif","still":"./media/pagination-6-still.png","height":286,"alt":"offset у конца, limit большой. граница ограничена len(ids).","practice":"Проверь частичную страницу, пустой вход и большой limit.","code":"got := Page([]string{\"A\", \"B\"}, 1, 100)","production":"Тест на большую границу ловит выход за пределы и переполнение при сложении."}]
  ]},
  {"id":"retry","category":"Backend","section":"Context, timeouts и retry","sources":["https://github.com/goavengers/go-interview/tree/master/docs/golang","https://github.com/yakomisar/golang-questions"],"theory":[
    ["Зачем нужен context","Когда пользователь закрыл запрос, дедлайн истёк или вызывающий сервис отменил операцию, дочерняя работа не должна бесконтрольно продолжаться. Context переносит сигнал отмены, дедлайн и ограниченные request-scoped значения, а не служит общей картой параметров.",{"animation":"./media/retry-1.gif","still":"./media/retry-1-still.png","height":286,"alt":"внешний вызов временно упал. следующая попытка может пройти.","practice":"Ограничь число вызовов тремя.","code":"for i := 0; i < 3; i++ { /* попытка */ }","production":"Повтор может помочь при кратком сбое чтения внешнего API."}],
    ["Где проверять отмену","ctx.Done() — канал завершения, ctx.Err() сообщает причину (Canceled или DeadlineExceeded). Блокирующие операции и ожидания должны иметь путь завершения при отмене. Просто принять ctx аргументом недостаточно: его нужно передавать вниз и учитывать.",{"animation":"./media/retry-2.gif","still":"./media/retry-2-still.png","height":286,"alt":"ctx отменён перед попыткой. fn больше не вызывается.","practice":"Проверяй ctx.Err до каждого вызова.","code":"if err := ctx.Err(); err != nil { return err }","production":"Передавай ctx самой сетевой операции, чтобы она могла остановиться во время вызова."}],
    ["Retry и идемпотентность","Повтор неидемпотентной операции может создать двойное событие, платеж или сообщение. Перед добавлением retry выясни, какие ошибки временные, можно ли безопасно повторять действие и как будет обеспечена идемпотентность — ключом запроса, дедупликацией или транзакционным механизмом.",{"animation":"./media/retry-3.gif","still":"./media/retry-3-still.png","height":286,"alt":"первая попытка списала деньги. ответ потерян, запрос повторён.","practice":"В задаче fn задана. Перед переиспользованием проверь, безопасен ли повтор.","code":"err := fn()","production":"Изменяющий запрос обычно повторяют с ключом идемпотентности, если API поддерживает такой контракт."}],
    ["Backoff и jitter","Немедленные повторы всех клиентов могут перегрузить восстанавливающийся сервис. Exponential backoff с jitter помогает распределить нагрузку, но должен учитывать общий дедлайн и лимит попыток. Не делай sleep, игнорирующий context cancellation.",{"animation":"./media/retry-4.gif","still":"./media/retry-4-still.png","height":286,"alt":"несколько клиентов получили сбой. случайная задержка разводит повторы.","practice":"Три попытки в kata идут сразу. Таймер можно добавить отдельно.","code":"select { case <-ctx.Done(): return ctx.Err(); case <-timer.C: }","production":"Backoff с jitter снижает одновременную нагрузку на восстанавливающийся сервис."}],
    ["Последняя ошибка и observability","После всех попыток возвращай информативную причину, при отмене — ctx.Err(). Метрики retries и причины ошибок помогут отличить временный сбой от постоянной деградации. Логи каждого повтора не должны создавать неконтролируемый шум.",{"animation":"./media/retry-5.gif","still":"./media/retry-5-still.png","height":286,"alt":"попытки: e1, e2, e3. после исчерпания возвращаем e3.","practice":"Запоминай последнюю ошибку и возвращай её после цикла.","code":"last = err","production":"Метрики попыток помогают отличить редкие повторы от системного сбоя."}],
    ["Практика","Сначала реализуй Retry на три попытки без задержки для понятного теста. Затем добавь timeout/backoff и тесты без реального ожидания через внедряемые часы или задержки. Расскажи, почему retry не заменяет идемпотентность Kafka consumer.",{"animation":"./media/retry-6.gif","still":"./media/retry-6-still.png","height":286,"alt":"вызовы: ошибка, ошибка, успех. результат nil, вызовов три.","practice":"В тесте подставь fn, которая меняет ответ по номеру вызова.","code":"err := Retry(ctx, fn)","production":"Детерминированные заглушки проверяют политику повторов без сетевых сбоев."}]
  ]},
  {"id":"race","category":"Concurrency","section":"Goroutines: data race и синхронизация","sources":["https://github.com/yakomisar/golang-questions#goroutines-и-channels","https://github.com/goavengers/go-interview/tree/master/docs/popular_tasks"],"theory":[
    ["Конкурентность — не параллелизм","Concurrency описывает организацию нескольких независимых задач; parallelism — их одновременное исполнение на разных вычислительных ресурсах. В Go goroutine — лёгкая единица конкурентной работы, которую планирует Go runtime, а не обязательно отдельный поток ОС.",{"animation":"./media/race-1.gif","still":"./media/race-1-still.png","height":286,"alt":"две горутины работают с value. операции могут чередоваться.","practice":"Защити общее поле счётчика.","code":"type Counter struct { mu sync.Mutex; value int }","production":"Один счётчик статистики может обновляться несколькими обработчиками."}],
    ["Что означает count++","Операция count++ состоит из чтения, вычисления и записи. Две горутины могут прочитать одно старое значение и обе записать одинаковый результат, потеряв инкремент. Это data race, если конфликтующие обращения не синхронизированы.",{"animation":"./media/race-2.gif","still":"./media/race-2-still.png","height":286,"alt":"G1 читает 0, G2 читает 0. обе записывают 1 → потерян инкремент.","practice":"Сделай чтение, сложение и запись одной критической секцией.","code":"c.mu.Lock(); defer c.mu.Unlock(); c.value++","production":"Так два одновременных сообщения учитываются оба."}],
    ["Mutex и atomic","Mutex защищает критическую секцию с несколькими операциями; atomic подходит для определённых простых атомарных действий. Чтение общей переменной тоже должно быть синхронизировано. Нельзя просто добавить mutex в один метод и оставить Value без защиты.",{"animation":"./media/race-3.gif","still":"./media/race-3-still.png","height":286,"alt":"Mutex охватывает чтение и запись. атомик подходит для одного числа.","practice":"Используй один mutex в Inc и Value.","code":"c.mu.Lock(); defer c.mu.Unlock(); return c.value","production":"Для нескольких взаимосвязанных полей mutex позволяет защитить общий инвариант."}],
    ["WaitGroup и утечки","WaitGroup ждёт завершения набора задач, но сам по себе не защищает общий счётчик. Отмена context тоже не останавливает произвольную горутину автоматически — рабочая функция должна её учитывать. При неверном жизненном цикле возможны goroutine leaks.",{"animation":"./media/race-4.gif","still":"./media/race-4-still.png","height":286,"alt":"горутины запущены. wg.Wait ждёт завершения всех.","practice":"В тесте считай итог после завершения работников.","code":"wg.Wait()","production":"При остановке сервиса сначала дай работникам завершиться, затем читай финальную статистику."}],
    ["Race detector","go test -race инструментирует программу и обнаруживает многие реальные гонки во время выполнения. Отсутствие отчёта не доказывает, что гонок нет: код должен исполнить конфликтующие пути. Race detector и логические race conditions — не одно и то же.",{"animation":"./media/race-5.gif","still":"./media/race-5-still.png","height":286,"alt":"обычный тест может пройти. race detector замечает конфликтующие доступы.","practice":"Запусти конкурентный тест с race detector.","code":"go test -race -run '^TestCounter$'","production":"Race-проверка на CI ловит обращения, которые встретились в тестовом прогоне."}],
    ["Практика","Создай тест с 100 горутинами, запусти с -race. Почини через Mutex. Затем попробуй atomic.Int64, объясни trade-offs и добавь конкурентное чтение. Для Senior собеседования будь готов различать data race, deadlock и goroutine leak.",{"animation":"./media/race-6.gif","still":"./media/race-6-still.png","height":286,"alt":"1000 вызовов Inc. после Wait ожидаем 1000.","practice":"Проверь итог и запускай конкурентную проверку.","code":"if got := c.Value(); got != 1000 { t.Fatal(got) }","production":"Тест защищает и при изменении способа синхронизации."}]
  ]},
  {"id":"typednil","category":"Go Core","section":"Интерфейсы: typed nil","sources":["https://github.com/goavengers/go-interview/tree/master/docs/golang","https://github.com/yakomisar/golang-questions"],"theory":[
    ["Что такое интерфейс","Интерфейс в Go описывает набор методов. Тип удовлетворяет интерфейсу не через явное implements, а если его method set содержит необходимые методы. Это помогает отделять бизнес-логику от конкретной реализации хранения или транспорта.",{"animation":"./media/typednil-1.gif","still":"./media/typednil-1-still.png","height":286,"alt":"error хранит тип и значение. nil interface: типа и значения нет.","practice":"Отличай nil-указатель от nil error.","code":"var err error","production":"Эта разница влияет на проверки ошибок на границе handler."}],
    ["Почему nil бывает разным","Значение интерфейса концептуально включает динамический тип и динамическое значение. Полностью nil interface не имеет ни того, ни другого. Если присвоить в error указатель типа *MyError со значением nil, у интерфейса будет динамический тип — поэтому err != nil.",{"animation":"./media/typednil-2.gif","still":"./media/typednil-2-still.png","height":286,"alt":"var p *MyError = nil. error(p): тип *MyError, значение nil.","practice":"При успехе возвращай literal nil.","code":"if !fail { return nil }","production":"Иначе middleware может записать успешный запрос как ошибку."}],
    ["Как возникает баг","Функция создаёт var e *MyError, затем возвращает e как error. Даже без ошибки вызывающий получает ненулевой interface. Если обратиться к методу Error() на nil receiver без защиты, может возникнуть panic — это зависит от реализации метода.",{"animation":"./media/typednil-3.gif","still":"./media/typednil-3-still.png","height":286,"alt":"функция возвращает p как error. err != nil → ложная ветка сбоя.","practice":"Формируй объект ошибки только в ветке fail.","code":"return &MyError{}","production":"Ложная ошибка может вызвать ненужный retry внешнего запроса."}],
    ["Правильный контракт","Если ошибки нет, верни literal nil из функции с результатом error. Если есть ошибка, создай конкретное значение. Не полагайся на сравнение текста Error() или на то, что печать nil-указателя выглядит как <nil>.",{"animation":"./media/typednil-4.gif","still":"./media/typednil-4-still.png","height":286,"alt":"успех → nil. сбой → &MyError{}.","practice":"Покрой обе ветки контракта MaybeError.","code":"if err := MaybeError(false); err != nil { t.Fatal(err) }","production":"Клиентская библиотека опирается на nil как признак успешного вызова."}],
    ["Method set и receiver","Методы с receiver T входят в method set T и *T; методы с receiver *T входят в method set *T, но не T. Это влияет на то, можно ли присвоить значение конкретного типа переменной интерфейсного типа.",{"animation":"./media/typednil-5.gif","still":"./media/typednil-5-still.png","height":286,"alt":"Error объявлен на *MyError. *MyError удовлетворяет error.","practice":"Проверь реализацию интерфейса на этапе компиляции.","code":"var _ error = (*MyError)(nil)","production":"Такая проверка полезна для пользовательских ошибок в адаптерах."}],
    ["Практика","Исправь MaybeError, добавь проверку `err == nil`, напиши пример typed nil. Объясни, почему сравнение с nil интерфейса и проверка его динамического значения — разные операции.",{"animation":"./media/typednil-6.gif","still":"./media/typednil-6-still.png","height":286,"alt":"fail=false → nil. fail=true → ненулевой error.","practice":"Объясни динамический тип возвращённого значения в обоих случаях.","code":"ok := MaybeError(false) == nil","production":"Регрессионный тест ловит возврат typed nil после рефакторинга."}]
  ]},
  {"id":"map-count","category":"Go Core","section":"Map: подсчёт, comma-ok, порядок и конкурентность","sources":["https://github.com/yakomisar/golang-questions/blob/main/README.md","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Где встречается в backend","Представь список событий календаря: активное, отменённое, снова активное. В API нужно отдать счётчики по статусам. Можно сделать несколько циклов, но удобнее один проход и map, где ключ — статус, значение — число. На проде аналогично считают ошибки по категориям, типы сообщений и частоты реакций.",{"animation":"./media/map-count-1.gif","still":"./media/map-count-1-still.png","height":286,"alt":"active, cancelled, active. active=2, cancelled=1.","practice":"Используй статус как ключ, число событий как значение.","code":"counts[ev.Status]++","production":"Так можно собрать счётчики интерфейса по уже загруженным событиям."}],
    ["Как устроен map","Запись map[string]int означает отображение из строки в целое число. Go использует хеширование ключа и внутреннюю структуру поиска элементов. Конкретное внутреннее устройство меняется между версиями Go: на интервью важно объяснить хеширование, сравнимость ключей, среднюю сложность поиска и то, что точный порядок обхода не гарантируется.",{"animation":"./media/map-count-2.gif","still":"./media/map-count-2-still.png","height":286,"alt":"ключ active → число. повтор active → обновление ключа.","practice":"Создай map для накопления счётчиков.","code":"counts := make(map[string]int)","production":"Строковые ключи удобно использовать для заранее определённых статусов."}],
    ["Нулевые значения и nil","При чтении отсутствующего статуса counts[\"active\"] возвращает 0: это zero value int. Поэтому можно сразу делать counts[status]++. Но отсутствие и реальный ноль различают через value, ok := counts[key]. var counts map[string]int создаёт nil map, читать из неё можно, записывать — panic. make(map[string]int) или литерал создают пригодную для записи карту.",{"animation":"./media/map-count-3.gif","still":"./media/map-count-3-still.png","height":286,"alt":"нет ключа → читаем 0. первый ++ → запись 1.","practice":"Инициализируй map перед записью.","code":"counts := make(map[string]int)","production":"Нулевая map годится для чтения, а запись в неё вызывает panic."}],
    ["range, удаление и порядок","for _, event := range events выдаёт копию текущего элемента среза. У map порядок итерации не определён, поэтому его нельзя использовать для стабильной сортировки JSON-отчёта. Если нужен порядок статусов, собери ключи в срез, отсортируй и затем выведи значения. Удаление из map — delete; clear очищает карту, но не делает её nil.",{"animation":"./media/map-count-4.gif","still":"./media/map-count-4-still.png","height":286,"alt":"обход map → порядок произвольный. сортировка ключей → стабильный вывод.","practice":"Возвращай map и сравнивай значения по ключам.","code":"active := CountStatuses(events)[\"active\"]","production":"Для упорядоченной выгрузки сначала отсортируй ключи."}],
    ["Безопасность при нескольких горутинах","Обычный map не предназначен для конкурентных записей и не синхронизирован с конкурентными чтениями. Несинхронизированные обращения могут привести к data race и ошибкам runtime. Для совместного доступа используй mutex, разделение владения между горутинами или подходящую альтернативу вроде sync.Map для специфических сценариев. В обычном локальном подсчёте дополнительная синхронизация не нужна.",{"animation":"./media/map-count-5.gif","still":"./media/map-count-5-still.png","height":286,"alt":"G1 и G2 пишут в общую map. локальные map → объединяем после работы.","practice":"Держи counts внутри вызова CountStatuses.","code":"counts := make(map[string]int)","production":"Для долгоживущих общих счётчиков нужна синхронизация или единый владелец."}],
    ["Как построить решение и объяснить на собеседовании","Сначала определи тип результата и контракт пустого входа. Затем создай map, пройди события, сделай инкремент по Status. Ожидаемая сложность O(n) по времени и O(k) по дополнительной памяти, где k — число уникальных статусов. В тестах проверь повторяющиеся значения, пустой вход и то, что исходные события не изменились. На собеседовании объясни, почему возвращаешь не nil map и почему map не гарантирует порядок ключей.",{"animation":"./media/map-count-6.gif","still":"./media/map-count-6-still.png","height":286,"alt":"один проход по событиям. map содержит только встреченные статусы.","practice":"Проверь пустой вход и несколько событий одного статуса.","code":"if got[\"active\"] != 2 { t.Fatal(got) }","production":"При подсчёте большого набора, который ещё в БД, рассмотрим GROUP BY."}]
  ]},
  {"id":"utf8-truncate","category":"Go Core","section":"Строки: UTF-8, byte, rune и Unicode","sources":["https://github.com/yakomisar/golang-questions/blob/main/README.md","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Зачем Unicode backend-разработчику","Имя пользователя, текст сообщения, название события могут содержать кириллицу, иероглифы и эмодзи. Клиент просит обрезать строку до N символов. Наивное s[:N] берёт первые N байтов и способно разрезать многобайтовую последовательность UTF-8. В результате получим повреждённые данные.",{"animation":"./media/utf8-truncate-1.gif","still":"./media/utf8-truncate-1-still.png","height":286,"alt":"имя: A, Ж, 🙂. три code points, семь байт.","practice":"Считай Unicode code points для ограничения задачи.","code":"got := TruncateRunes(\"AЖ🙂\", 2)","production":"Так можно ограничить длину превью имени по code points."}],
    ["Что хранит string","Строка Go — неизменяемая последовательность байтов. Тип string сам по себе не гарантирует корректный UTF-8, хотя большинство прикладных строк используют именно эту кодировку. len(s) возвращает число байтов. Индексация s[i] возвращает один byte, а не Unicode-символ. Операция s[:end] создаёт подстроку по байтовой границе.",{"animation":"./media/utf8-truncate-2.gif","still":"./media/utf8-truncate-2-still.png","height":286,"alt":"A: 1 байт, Ж: 2 байта. s[:2] разрезает Ж.","practice":"Возвращай срез строки на границе UTF-8.","code":"return s[:i]","production":"На границе сервиса JSON должен содержать корректный текст."}],
    ["Что такое rune и range","rune — псевдоним int32 для Unicode code point. Цикл for i, r := range s декодирует UTF-8 и возвращает байтовый индекс i и rune r. Например, в \"AЯ\" len равно 3 байта, но через range будут две итерации. Для некорректной UTF-8 последовательности range выдаёт RuneError. Чтобы посчитать code points, можно использовать utf8.RuneCountInString.",{"animation":"./media/utf8-truncate-3.gif","still":"./media/utf8-truncate-3-still.png","height":286,"alt":"range: A в 0, Ж в 1, 🙂 в 3. i указывает на начало code point.","practice":"Используй индекс из range как границу среза.","code":"for i := range s { /* i — смещение в байтах */ }","production":"Так не нужно выделять весь []rune при формировании короткого превью."}],
    ["Почему rune не всегда равен видимому символу","Существуют составные последовательности Unicode: базовая буква плюс combining mark, эмодзи с модификаторами, ZWJ-последовательности. Пользователь может воспринимать их как один символ, хотя они включают несколько rune. Для корректного ограничения по видимым графемам нужен алгоритм сегментации grapheme clusters, а не простой range. В нашей первой задаче требование явно задаёт число rune.",{"animation":"./media/utf8-truncate-4.gif","still":"./media/utf8-truncate-4-still.png","height":286,"alt":"e + combining accent. два code points, один видимый знак.","practice":"В задаче единица длины — code point.","code":"got := TruncateRunes(\"e\\u0301\", 1)","production":"Для ограничения видимых символов используют сегментацию grapheme clusters."}],
    ["Как не сломать UTF-8 при обрезке","Нужно искать байтовую позицию, с которой начинается (max+1)-я rune, и возвращать s[:i]. Такой срез проходит только по границам code points. Если max<=0 — пустая строка; если rune меньше max — возвращаем исходную строку. Это линейный проход по длине текста. Прежде чем использовать алгоритм в реальном API, уточни требования: code points, graphemes или bytes.",{"animation":"./media/utf8-truncate-5.gif","still":"./media/utf8-truncate-5-still.png","height":286,"alt":"max=2, очередной индекс=3. s[:3] → AЖ.","practice":"Верни префикс на начале следующей руны, если уже набрал max.","code":"if count == max { return s[:i] }","production":"Имя с кириллицей и эмодзи остаётся валидным UTF-8 для валидного входа."}],
    ["Что чаще спрашивают на интервью","Почему len(\"Привет\") больше шести? Чем различаются []byte(s) и []rune(s)? Что делает range по строке? Можно ли менять отдельный байт string? Как эффективно собирать текст через strings.Builder? Ответ должен описывать байтовое представление, UTF-8, стоимость преобразований и ограничения понятия rune. На практике добавь тесты с кириллицей, эмодзи, ASCII и пустым текстом.",{"animation":"./media/utf8-truncate-6.gif","still":"./media/utf8-truncate-6-still.png","height":286,"alt":"max<=0 → пусто. max больше длины → вся строка.","practice":"Проверь ASCII, кириллицу и эмодзи.","code":"if max <= 0 { return \"\" }","production":"Тесты на многоязычном вводе ловят байтовую обрезку."}]
  ]},
  {"id":"channel-merge","category":"Concurrency","section":"Каналы: fan-in, закрытие и отмена","sources":["https://github.com/yakomisar/golang-questions/blob/main/README.md","https://github.com/goavengers/go-interview/tree/master/docs/popular_tasks"],"theory":[
    ["Сценарий из realtime-сервиса","Есть два независимых источника событий, каждый передаёт сообщения через свой канал. Клиенту нужен один выходной поток. Это паттерн fan-in. Важно не только скопировать значения, но и корректно завершить goroutines и закрыть выход, особенно когда запрос отменён.",{"animation":"./media/channel-merge-1.gif","still":"./media/channel-merge-1-still.png","height":286,"alt":"a: 1, 3; b: 2, 4. out получает все четыре значения.","practice":"Запусти по пересыльщику на источник.","code":"go forward(a); go forward(b)","production":"Так объединяют два потока realtime-событий."}],
    ["Что такое канал","Канал Go передаёт типизированные значения между goroutines. Отправка и чтение через unbuffered channel синхронизируются между отправителем и получателем. Buffered channel содержит очередь заданной ёмкости, поэтому отправитель может продолжать до заполнения буфера. Канал nil блокирует отправку и чтение навсегда без других механизмов выхода.",{"animation":"./media/channel-merge-2.gif","still":"./media/channel-merge-2-still.png","height":286,"alt":"получили v из входа. передаём v дальше.","practice":"Раздели каналы на входы только для чтения и выход.","code":"out := make(chan int)","production":"Типы направлений помогают закрепить контракт владения."}],
    ["Правила закрытия","Отправка в закрытый канал вызывает panic. Чтение из закрытого и исчерпанного канала сразу возвращает zero value и ok=false. for value := range channel заканчивается после закрытия и опустошения. В простом fan-in входы закрывают их владельцы, а выход закрывается одной goroutine после завершения всех отправителей. Не закрывай выход из каждого worker-а независимо.",{"animation":"./media/channel-merge-3.gif","still":"./media/channel-merge-3-still.png","height":286,"alt":"a закрылся, b ещё пишет. out открыт до завершения b.","practice":"Закрывай out единожды после завершения обоих пересыльщиков.","code":"wg.Wait(); close(out)","production":"Читатель может дочитать весь объединённый поток без риска send on closed channel."}],
    ["Как работают select и context","select ждёт готовности одной из операций. При одновременной готовности нескольких веток выбор не гарантирует конкретный порядок. Чтобы worker не завис навечно, добавь ветку <-ctx.Done() и при ожидании входа, и при отправке в out. Контекст не убивает goroutine автоматически; код сам должен слушать сигнал отмены.",{"animation":"./media/channel-merge-4.gif","still":"./media/channel-merge-4-still.png","height":286,"alt":"читатель out ушёл. ctx.Done разблокирует отправителя.","practice":"Проверяй отмену на чтении и на отправке.","code":"select { case out <- value: case <-ctx.Done(): return }","production":"Остановка подписки освобождает горутины даже при медленном клиенте."}],
    ["Почему нужен WaitGroup","Два worker-а независимо вычитывают входы. Когда один закончится, другой ещё может отправлять значения. Закрывать out после первого нельзя. sync.WaitGroup позволяет дождаться обоих, затем закрыть out ровно один раз. Внимательно расставь Add(2) до запуска goroutines и Done() через defer.",{"animation":"./media/channel-merge-5.gif","still":"./media/channel-merge-5-still.png","height":286,"alt":"wg.Add(2) перед запуском. два Done → Wait завершён.","practice":"Регистрируй работников до старта.","code":"defer wg.Done()","production":"Координатор завершает выходной поток после всех производителей."}],
    ["Тесты и разбор на собеседовании","Тестируй завершение двух закрытых входов, отсутствие потери значений, отмену контекста и ситуацию, когда потребитель перестал читать. Для concurrency-тестов не привязывайся к порядку между независимыми источниками. Проверяй завершение с таймаутом, чтобы зависание не блокировало весь набор тестов. На интервью объясни ownership каналов, backpressure, утечки goroutines и отличие fan-in от worker pool.",{"animation":"./media/channel-merge-6.gif","still":"./media/channel-merge-6-still.png","height":286,"alt":"между потоками порядок меняется. сравниваем набор полученных значений.","practice":"Тестируй закрытие и отмену при заблокированной отправке.","code":"for value := range out { got = append(got, value) }","production":"Проверка с дедлайном выявляет зависания при остановке."}]
  ]},
  {"id":"http-health","category":"Backend","section":"HTTP handler: контракты и тестирование","sources":["https://github.com/goavengers/go-interview/tree/master/docs/common","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Зачем backend health endpoint","Инфраструктура может регулярно спрашивать сервис, доступен ли он для трафика. Простейший handler возвращает HTTP 200 и JSON с состоянием. В реальном сервисе важно различать liveness (жив процесс) и readiness (можно отправлять запросы), но в этой задаче мы отрабатываем фундамент: контракт HTTP-ответа.",{"animation":"./media/http-health-1.gif","still":"./media/http-health-1-still.png","height":286,"alt":"probe вызывает /health. 200 и JSON status=ok.","practice":"Возвращай простой ответ для проверки жизни процесса.","code":"json.NewEncoder(w).Encode(map[string]string{\"status\":\"ok\"})","production":"Оркестратор может использовать endpoint как liveness probe."}],
    ["Как устроен net/http","Интерфейс http.Handler содержит ServeHTTP(http.ResponseWriter, *http.Request). http.HandlerFunc превращает обычную функцию подходящей сигнатуры в Handler. Request содержит метод, путь, заголовки, тело и context. ResponseWriter позволяет выставить заголовки, статус и записать тело.",{"animation":"./media/http-health-2.gif","still":"./media/http-health-2-still.png","height":286,"alt":"запрос входит в HandlerFunc. ответ уходит через ResponseWriter.","practice":"Реализуй функцию с сигнатурой net/http.","code":"func HealthHandler(w http.ResponseWriter, r *http.Request)","production":"Маршрутизатор вызывает handler одинаково для обычных API и проверок."}],
    ["В каком порядке писать ответ","Вызови w.Header().Set(\"Content-Type\", \"application/json\") до первого Write или WriteHeader. Если не указать статус, первый Write неявно отправляет 200. После начала записи заголовков менять их обычно поздно. json.NewEncoder(w).Encode(value) сериализует объект в поток. Ошибку Encode стоит учитывать в серьёзном коде, если её можно корректно обработать.",{"animation":"./media/http-health-3.gif","still":"./media/http-health-3-still.png","height":286,"alt":"сначала Content-Type. затем запись тела фиксирует статус.","practice":"Установи заголовок до Encode.","code":"w.Header().Set(\"Content-Type\", \"application/json\")","production":"Клиент и мониторинг получат корректный MIME-тип."}],
    ["Тест без настоящего порта","httptest.NewRequest создаёт тестовый запрос. httptest.NewRecorder — ResponseRecorder, который запоминает код, заголовки и тело. Ты вызываешь HealthHandler(recorder, request) и проверяешь recorder.Code, Header().Get(...) и JSON в Body. Это гораздо быстрее и детерминированнее запуска отдельного HTTP-сервера.",{"animation":"./media/http-health-4.gif","still":"./media/http-health-4-still.png","height":286,"alt":"httptest создаёт запрос. recorder сохраняет статус и тело.","practice":"Вызови обработчик напрямую.","code":"HealthHandler(httptest.NewRecorder(), httptest.NewRequest(\"GET\", \"/health\", nil))","production":"Unit-тест проверяет HTTP-контракт без сетевого порта."}],
    ["Что спрашивают на собеседовании","Как написать middleware? Как передать context из Request в service? Чем отличаются status code и тело JSON? Как отличить 400 от 500? Как обрабатывать декодирование входного JSON? Почему нельзя без лимита читать request.Body? Часто дают небольшой handler и просят написать тесты на успешный ответ и ошибку.",{"animation":"./media/http-health-5.gif","still":"./media/http-health-5-still.png","height":286,"alt":"тело записано без WriteHeader. статус по умолчанию 200.","practice":"Объясни момент фиксации заголовков.","code":"w.WriteHeader(http.StatusOK)","production":"Запись заголовка после тела уже не изменит отправленный ответ."}],
    ["Практика production-уровня","Сделай отдельные liveness и readiness endpoints, но не подключай к liveness тяжёлые проверки базы. Реализуй timeout для внешних зависимостей, корректно ограничь тело запросов и не пиши секреты в ответы. После успешной базовой задачи переходи к middleware, валидации и таблице тестовых HTTP-кейсов.",{"animation":"./media/http-health-6.gif","still":"./media/http-health-6-still.png","height":286,"alt":"процесс жив. зависимость недоступна → readiness может упасть.","practice":"Оставь HealthHandler простой проверкой жизни.","code":"mux.HandleFunc(\"/health\", HealthHandler)","production":"Для readiness заведите отдельную проверку готовности принимать запросы."}]
  ]},
  {"id":"event-pointer","category":"Go Core","section":"Указатели: value semantics и безопасная мутация","sources":["https://github.com/yakomisar/golang-questions/blob/main/README.md","https://github.com/goavengers/go-interview/tree/master/docs/golang"],"theory":[
    ["Зачем это в реальном сервисе","Представь, что handler получил событие с ID и статусом, а сервис хочет перевести его в cancelled. Если передать Event как значение и изменить поле внутри функции, изменится только локальная копия. Если функция должна изменять тот же объект, она может принимать *Event. Однако не всякий pointer нужен: если функция должна вернуть новый независимый результат, value semantics могут быть правильнее.",{"animation":"./media/event-pointer-1.gif","still":"./media/event-pointer-1-still.png","height":286,"alt":"event.Status = active. обновление через указатель → cancelled.","practice":"Проверь допустимый статус перед записью.","code":"event.Status = status","production":"В сервисе это помогает обновить модель события перед сохранением."}],
    ["Как аргументы передаются в Go","Все аргументы функции передаются по значению. При передаче структуры копируются её поля. При передаче *Event копируется указатель, который продолжает указывать на тот же объект. Запись event.Status = \"cancelled\" меняет исходную структуру. Поэтому выражение «в Go есть передача по ссылке» вводит в заблуждение: механизм — копирование значения указателя.",{"animation":"./media/event-pointer-2.gif","still":"./media/event-pointer-2-still.png","height":286,"alt":"копия Event имеет свои поля. копия *Event указывает на тот же Event.","practice":"Передавай адрес, чтобы изменить исходную модель.","code":"err := UpdateEventStatus(&event, \"cancelled\")","production":"Явная мутация полезна, когда вызывающий код владеет моделью."}],
    ["Оператор & и разыменование *","Оператор &x получает адрес адресуемой переменной. Тип *T означает указатель на значение типа T; оператор *p читает или меняет значение по этому адресу. Для полей структуры Go допускает сокращение p.Status вместо (*p).Status. Указатель может быть nil, и обращение через nil pointer вызывает panic; перед мутацией требуется проверка, если nil допустим контрактом.",{"animation":"./media/event-pointer-3.gif","still":"./media/event-pointer-3-still.png","height":286,"alt":"&event даёт адрес. event.Status разыменовывает указатель.","practice":"Проверь nil до чтения или записи.","code":"if event == nil { return errors.New(\"nil event\") }","production":"Проверка защищает от panic при отсутствии объекта."}],
    ["Стек, heap и escape analysis","Нельзя утверждать, что любое использование &x автоматически создаёт heap allocation. Компилятор оценивает время жизни значения и возможность доступа за пределами области вызова. Даже локальные объекты могут попадать в heap, если они escaping; наоборот, адрес локальной переменной может оставаться на стеке. Экспериментируют с `go build -gcflags='-m=2'`, но вывод зависит от оптимизаций и версии Go.",{"animation":"./media/event-pointer-4.gif","still":"./media/event-pointer-4-still.png","height":286,"alt":"локальный объект → указатель. компилятор выбирает размещение.","practice":"Выбирай указатель ради семантики изменения.","code":"ptr := &event","production":"Для горячего пути смотри escape analysis и аллокации бенчмарка."}],
    ["Инварианты и aliasing в backend","Если несколько частей программы держат указатель на одно Event, изменение статуса видно всем владельцам ссылок. Это упрощает обновление, но создаёт риск неожиданной мутации. В конкурентном коде shared mutable state требует синхронизации. Валидируй вход до изменения: при неизвестном статусе или nil значение события не должно меняться частично.",{"animation":"./media/event-pointer-5.gif","still":"./media/event-pointer-5-still.png","height":286,"alt":"два указателя → одна модель. запись видна через оба.","practice":"Отклоняй неверный статус до мутации.","code":"if status != \"active\" && status != \"cancelled\" { return errors.New(\"invalid status\") }","production":"Модель с общими владельцами требует согласованного доступа."}],
    ["Как проверяют на собеседовании и в код-ревью","Ожидают, что ты объяснишь значение и указатель, nil, мутацию и разницу со slice header. Затем могут попросить предсказать вывод, реализовать Swap или исправить баг, где функция меняет копию структуры. В задаче UpdateEventStatus напиши проверки nil и статуса, затем изменение поля. Добавь тест, что на ошибочном входе исходное событие осталось прежним.",{"animation":"./media/event-pointer-6.gif","still":"./media/event-pointer-6-still.png","height":286,"alt":"invalid → ошибка. исходное значение сохраняется.","practice":"В тесте сравни статус до и после ошибки.","code":"err := UpdateEventStatus(&event, \"unknown\")","production":"Регрессия на мутацию важна перед записью события в хранилище."}]
  ]},
  {"id":"activity-methods","category":"Go Core","section":"Структуры и методы: receiver и инварианты","sources":["https://github.com/goavengers/go-interview/blob/master/README.md","https://github.com/yakomisar/golang-questions/blob/main/README.md"],"theory":[
    ["Сценарий мессенджера","Сервис хранит время последней активности чата и число непрочитанных сообщений. Новое событие должно продвинуть активность только вперёд. Вместо набора несвязанных переменных удобно завести структуру ChatActivity и метод ApplyMessage. Метод хранит правило непосредственно рядом с данными, которые он меняет.",{"animation":"./media/activity-methods-1.gif","still":"./media/activity-methods-1-still.png","height":286,"alt":"LastMessageAt=100, Unread=2. при at=120 получаем 120 и 3.","practice":"Обновляй оба поля только для более нового timestamp.","code":"a.LastMessageAt = at; a.Unread++","production":"Так учебная модель чата применяет обновление активности."}],
    ["Структуры и zero value","Struct объединяет поля, например LastMessageAt int64 и Unread int. Нулевое значение ChatActivity{LastMessageAt:0,Unread:0} уже полезно как состояние без сообщений. Поля структуры копируются при присваивании значения, а не остаются автоматически общими. Если поле само содержит slice, копируется только описатель этого slice, и его элементы могут оставаться общими.",{"animation":"./media/activity-methods-2.gif","still":"./media/activity-methods-2-still.png","height":286,"alt":"нулевая ChatActivity. первый положительный timestamp принимается.","practice":"Проверь вызов на zero value.","code":"var activity ChatActivity","production":"Нулевое состояние удобно для только что созданной модели."}],
    ["Value receiver против pointer receiver","func (a ChatActivity) M() получает копию структуры. Если присвоить a.Unread++, исходная структура не изменится. func (a *ChatActivity) M() получает копию указателя на исходный объект и может менять поля. Pointer receiver также обычно выбирают для больших структур, типов с состоянием или с mutex, который нельзя копировать после первого использования.",{"animation":"./media/activity-methods-3.gif","still":"./media/activity-methods-3-still.png","height":286,"alt":"value receiver → копия. pointer receiver → исходный объект.","practice":"Объяви ApplyMessage с pointer receiver.","code":"func (a *ChatActivity) ApplyMessage(at int64) bool","production":"Методы модели позволяют держать изменения полей вместе."}],
    ["Method set и interfaces","Method set типа T содержит методы с receiver T. Method set типа *T содержит методы с receiver T и *T. Это влияет на удовлетворение интерфейсу. Например, если интерфейс требует ApplyMessage, а метод объявлен с receiver *ChatActivity, интерфейсу удовлетворяет *ChatActivity, но не ChatActivity. Автоматическое взятие адреса при обычном вызове метода не меняет эти правила.",{"animation":"./media/activity-methods-4.gif","still":"./media/activity-methods-4-still.png","height":286,"alt":"метод на *ChatActivity. интерфейс реализует указатель.","practice":"Проверь соответствие интерфейсу на компиляции.","code":"var _ interface{ ApplyMessage(int64) bool } = (*ChatActivity)(nil)","production":"Проверка ловит несовпадение сигнатур адаптера."}],
    ["Контракт метода и nil receiver","Метод на указателе может быть вызван даже с nil receiver, если код не разыменовывает nil до проверки. В нашем упражнении nil означает отсутствие активности: метод возвращает false. Главное правило — не портить инварианты: at должен быть положительным и строго больше текущего времени; Unread увеличивается только если реальное обновление произошло.",{"animation":"./media/activity-methods-5.gif","still":"./media/activity-methods-5-still.png","height":286,"alt":"nil или at<=0. false, изменений нет.","practice":"Отклоняй nil, ноль, старые и равные timestamps.","code":"if a == nil || at <= 0 || at <= a.LastMessageAt { return false }","production":"Проверка защищает LastMessageAt от отката при запоздавшем обновлении."}],
    ["Практика и собеседование","Частые вопросы: чем struct отличается от interface, что такое receiver, что изменится при копировании struct и можно ли вызывать методы через nil pointer. Напиши ApplyMessage и таблицу тестов на нулевое состояние, повторную доставку timestamp, более старое событие и nil. После этого добавь тест на две разные копии ChatActivity и объясни, почему изменения одной не затронули другую.",{"animation":"./media/activity-methods-6.gif","still":"./media/activity-methods-6-still.png","height":286,"alt":"пришло 120, затем 110. второй вызов оставляет поля прежними.","practice":"Проверь оба поля после старого события.","code":"applied := activity.ApplyMessage(110)","production":"В проде дедупликацию сообщений и порядок событий задают отдельным контрактом."}]
  ]},
  {"id":"defer-cleanup","category":"Go Core","section":"defer, ошибки закрытия и errors.Join","sources":["https://github.com/MedUnes/go-kata/tree/master/04-errors-semantics/19-defer-cleanup-chain","https://github.com/goavengers/go-interview/blob/master/README.md"],"theory":[
    ["Зачем возвращать ошибку закрытия","После записи файла, завершения потока или работы с другим io.Closer необходимо вызвать Close. Иногда сама операция уже вернула ошибку, и Close тоже падает. Если вернуть только одну ошибку, потеряется важная информация. В production это проявляется как успешное завершение работы при неуспешной записи буфера или как потерянная причина сбоя.",{"animation":"./media/defer-cleanup-1.gif","still":"./media/defer-cleanup-1-still.png","height":286,"alt":"работа вернула e1. Close вернул e2 → сохраняем обе.","practice":"Объедини ошибки при выходе.","code":"err = errors.Join(err, closer.Close())","production":"Ошибка закрытия пишущего ресурса может означать потерю данных."}],
    ["Как устроен defer","defer регистрирует вызов для выполнения перед выходом из окружающей функции — включая обычный return и раскрутку panic. Несколько defer выполняются LIFO: последний зарегистрированный первым. Аргументы отложенного вызова вычисляются при выполнении оператора defer; замыкание может читать переменные позднее, когда вызов реально выполняется.",{"animation":"./media/defer-cleanup-2.gif","still":"./media/defer-cleanup-2-still.png","height":286,"alt":"функция регистрирует defer. отложенный вызов выполняется перед выходом.","practice":"Закрывай ресурс в отложенной функции.","code":"defer func() { err = errors.Join(err, closer.Close()) }()","production":"Так закрытие выполняется и на раннем return."}],
    ["Именованное возвращаемое значение","В функции `func F() (err error)` переменная err доступна в теле. При `return workErr` сначала присваивается возвращаемое значение, затем выполняются defer, после чего происходит окончательный выход. Поэтому deferred-замыкание может сделать `err = errors.Join(err, closer.Close())` и сохранить как исходную ошибку, так и ошибку закрытия. Это нужно делать осознанно, а не превращать все функции в именованные return.",{"animation":"./media/defer-cleanup-3.gif","still":"./media/defer-cleanup-3-still.png","height":286,"alt":"return workErr присваивает err. defer обновляет именованный err.","practice":"Используй именованное возвращаемое значение.","code":"func CloseWithError(workErr error, closer io.Closer) (err error)","production":"При нескольких путях выхода итог включает ошибку закрытия."}],
    ["errors.Join и цепочки","errors.Join возвращает nil, если все аргументы nil, иначе создаёт ошибку, которая разворачивается в набор причин. `errors.Is(joined, cause)` позволяет найти исходную ошибку даже при нескольких причинах. `errors.As` нужен, когда важно извлечь типизированную ошибку. `fmt.Errorf(\"...: %w\", err)` оборачивает причину и полезен для добавления контекста, но один %w и errors.Join решают немного разные задачи.",{"animation":"./media/defer-cleanup-4.gif","still":"./media/defer-cleanup-4-still.png","height":286,"alt":"Join(e1, e2). errors.Is находит e1 и e2.","practice":"Проверь обе причины через errors.Is.","code":"ok := errors.Is(err, workErr)","production":"Верхний слой сохраняет возможность классифицировать причины."}],
    ["Границы ответственности и Close","Не каждый Close может вернуть значимую ошибку после чтения, но для записи и flush риск существенно выше. Выбирай политику с учётом ресурса. Если closer может быть nil, проверь его до регистрации defer. Ошибку закрытия нельзя качественно обработать после того, как функция уже вернула окончательный результат, поэтому defer с именованным err помогает объединить причины перед выходом.",{"animation":"./media/defer-cleanup-5.gif","still":"./media/defer-cleanup-5-still.png","height":286,"alt":"владелец открыл ресурс. владелец закрывает его один раз.","practice":"При nil closer верни workErr.","code":"if closer == nil { return workErr }","production":"Договорись, какой слой владеет файлом или потоком."}],
    ["Что нужно сделать на практике","Напиши функцию CloseWithError, которая всегда вызывает Close ровно один раз при ненулевом closer. Проверь четыре сочетания: обе ошибки nil, ошибка только работы, только Close и обе сразу. Проверь `errors.Is` для каждой причины. На собеседовании объясни LIFO, время вычисления аргументов defer и почему прямой `defer closer.Close()` теряет ошибку Close.",{"animation":"./media/defer-cleanup-6.gif","still":"./media/defer-cleanup-6-still.png","height":286,"alt":"работа успешна, Close упал. результат содержит ошибку Close.","practice":"Проверь ошибки по отдельности и вместе.","code":"err := CloseWithError(workErr, fakeCloser)","production":"Fake позволяет проверить и причину, и число вызовов Close."}]
  ]},
  {"id":"worker-pool","category":"Concurrency","section":"Worker pool: bounded concurrency, ошибки и context","sources":["https://github.com/MedUnes/go-kata/tree/master/01-context-cancellation-concurrency/10-worker-pool-errors-join","https://github.com/goavengers/go-interview/tree/master/docs/popular_tasks"],"theory":[
    ["Зачем нужен worker pool","Представь, что нужно обработать 50 тысяч событий. Запускать отдельную goroutine на каждое событие без ограничений рискованно: можно перегрузить базу, внешнюю API и собственную память. Worker pool — фиксированное число обработчиков, которые берут задания из очереди. Так контролируется число одновременно выполняемых операций, а не количество всех заданий.",{"animation":"./media/worker-pool-1.gif","still":"./media/worker-pool-1-still.png","height":286,"alt":"1000 задач в очереди. N работников обрабатывают пачку.","practice":"Запусти фиксированное число воркеров.","code":"for i := 0; i < workers; i++ { go worker() }","production":"Ограничение защищает внешнюю зависимость от всплеска параллельных запросов."}],
    ["Каналы и распределение работы","Обычно одна сторона отправляет задания в jobs channel, а несколько worker-ов читают из него. Канал связывает отправителя и потребителя; unbuffered канал создаёт прямое ожидание, buffered — допускает очередь. Канал закрывает отправляющая сторона, когда новых заданий не будет. Work-канал не следует закрывать из нескольких worker-ов — это может привести к panic.",{"animation":"./media/worker-pool-2.gif","still":"./media/worker-pool-2-still.png","height":286,"alt":"один канал заданий. свободный работник забирает job.","practice":"Раздавай задания через канал work.","code":"work := make(chan int)","production":"Канал упрощает распределение пачки между обработчиками."}],
    ["Жизненный цикл горутин","sync.WaitGroup ждёт завершения всех worker-ов, но сам не обрабатывает ошибки и не отменяет работу. Add надо выполнить до запуска ожидаемых горутин, Done — гарантировать defer. Чтобы ограничить утечки, worker должен уметь выйти при закрытии work или при <-ctx.Done(). Потребитель, который навсегда блокируется при отправке и не слушает контекст, создаёт goroutine leak.",{"animation":"./media/worker-pool-3.gif","still":"./media/worker-pool-3-still.png","height":286,"alt":"подача закончилась. close(work) → все Done → Wait.","practice":"Закрывай канал со стороны производителя и дождись работников.","code":"close(work); wg.Wait()","production":"При остановке сервиса это позволяет завершить уже запущенную обработку."}],
    ["Fail-fast и error propagation","Для режима fail-fast первая ошибка fn должна привести к отмене дальнейшей раздачи. Несколько worker-ов могут ошибиться одновременно, поэтому общую firstErr требуется защищать sync.Once или другой синхронизацией. Отмена не является принудительным убийством fn: обработчик должен самостоятельно уважать переданный context. После отмены всё равно нужно дождаться завершения worker-ов через WaitGroup.",{"animation":"./media/worker-pool-4.gif","still":"./media/worker-pool-4-still.png","height":286,"alt":"worker вернул ошибку. первая ошибка отменяет общий ctx.","practice":"Сохрани первую ошибку через sync.Once.","code":"once.Do(func() { first = err; cancel() })","production":"Отмена передаёт остальным работникам сигнал остановиться."}],
    ["Backpressure, fairness и throughput","Увеличение workers не всегда ускоряет выполнение. При внешнем сервисе с ограничением RPS слишком высокая конкурентность порождает таймауты. При CPU-bound задачах оптимальное число исполнителей отличается от I/O-bound. Бенчмарки, latency percentiles и метрики очереди помогают найти баланс. Unbuffered очередь создаёт естественный backpressure; buffered позволяет сгладить короткие всплески, но скрывает перегрузку до заполнения.",{"animation":"./media/worker-pool-5.gif","still":"./media/worker-pool-5-still.png","height":286,"alt":"все воркеры заняты. отправитель ждёт свободного.","practice":"Делай отправку заданий с отменой.","code":"select { case work <- job: case <-ctx.Done(): break feed }","production":"Согласуй число работников с лимитами БД и бюджетом задержки."}],
    ["Проверка на собеседовании и в production","Нужно уметь нарисовать схему: producer → jobs → N workers → results/errors. Частые уточнения: кто закрывает канал, как не допустить утечек, что сделать при cancel, как вернуть ошибку, как не потерять data race. В ProcessJobs напиши ограниченное число workers, tests на максимум конкурентных fn, ошибку, отмену и неверную конфигурацию. Потом повтори без подсказок.",{"animation":"./media/worker-pool-6.gif","still":"./media/worker-pool-6-still.png","height":286,"alt":"воркер входит в fn. тест считает одновременные вызовы.","practice":"Проверь предел workers и возврат первой ошибки.","code":"err := ProcessJobs(ctx, jobs, 2, fn)","production":"На нагрузочных проверках отслеживай очередь, длительность и ошибки."}]
  ]},
  {"id":"http-middleware","category":"Backend","section":"HTTP middleware: валидация и цепочки handlers","sources":["https://github.com/MedUnes/go-kata/tree/master/03-http-middleware/06-interface-based-middleware-chain","https://github.com/goavengers/go-interview/tree/master/docs/common"],"theory":[
    ["Что делает middleware в реальном backend","HTTP handler выполняет конкретную бизнес-операцию, а middleware реализует общую обработку перед ней: идентификацию запроса, логирование, проверку авторизации, измерение latency, восстановление после panic. Если проверять X-Request-ID внутри каждого handler, логика будет повторяться и легко разойдётся. Middleware позволяет вынести её в одну точку.",{"animation":"./media/http-middleware-1.gif","still":"./media/http-middleware-1-still.png","height":286,"alt":"запрос → проверка ID. валидный → следующий handler.","practice":"Отклоняй запрос без X-Request-ID.","code":"id := strings.TrimSpace(r.Header.Get(\"X-Request-ID\"))","production":"ID запроса связывает логи нескольких операций одного вызова."}],
    ["Как выглядит контракт net/http","http.Handler — интерфейс с ServeHTTP(http.ResponseWriter,*http.Request). http.HandlerFunc адаптирует обычную функцию к этому интерфейсу. Middleware часто имеет тип func(http.Handler) http.Handler: получает следующий обработчик и возвращает обёртку. Внутри можно выполнить код до вызова next.ServeHTTP и после него, соблюдая правила ответа.",{"animation":"./media/http-middleware-2.gif","still":"./media/http-middleware-2-still.png","height":286,"alt":"middleware принимает Handler. возвращает обёрнутый Handler.","practice":"Используй адаптер http.HandlerFunc.","code":"return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { next.ServeHTTP(w, r) })","production":"Такие обёртки можно применять к разным маршрутам."}],
    ["Заголовки и статус ответа","Клиент отправляет request headers, сервер пишет response headers. Наш middleware читает r.Header.Get(\"X-Request-ID\"); если заголовок пустой или содержит пробелы, отвечает 400 JSON-ошибкой. Если валиден, вызывает next.ServeHTTP. Заголовки ответа надо установить до первого Write или WriteHeader: позднее изменение может не попасть в ответ.",{"animation":"./media/http-middleware-3.gif","still":"./media/http-middleware-3-still.png","height":286,"alt":"ID пустой → HTTP 400. return без вызова next.","practice":"Сначала пиши статус, затем JSON и return.","code":"w.WriteHeader(http.StatusBadRequest)","production":"Клиент получает ошибку контракта до выполнения бизнес-логики."}],
    ["Порядок middleware в цепочке","При композиции Logger(Auth(Handler)) первым выполняется внешний Logger, затем Auth, затем Handler; после возврата управление раскручивается в обратном порядке. Выбирай порядок осознанно: например, recovery обычно должен покрывать все внутренние обработчики. В реальном приложении middleware должен учитывать потоковые ответы, дополнительные интерфейсы ResponseWriter и время жизни request context.",{"animation":"./media/http-middleware-4.gif","still":"./media/http-middleware-4-still.png","height":286,"alt":"outer → inner → handler. после handler управление идёт обратно.","practice":"Определи, должен ли middleware видеть отклонённые запросы.","code":"handler := logger(RequestIDMiddleware(next))","production":"Внешний logger увидит HTTP 400, даже если основной handler не вызван."}],
    ["Тестирование без сервера","Используй httptest.NewRequest и httptest.NewRecorder. Для отсутствующего X-Request-ID проверь HTTP 400, JSON-ошибку и то, что next не вызвался. Для корректного заголовка проверь, что next вызван ровно один раз и исходный HTTP-ответ не испорчен. Это обычный unit-тест без порта, сети и Docker.",{"animation":"./media/http-middleware-5.gif","still":"./media/http-middleware-5-still.png","height":286,"alt":"recorder получает 400. fake next считает ноль вызовов.","practice":"Проверь оба пути через httptest.","code":"RequestIDMiddleware(next).ServeHTTP(rec, req)","production":"Так тест ловит случайный вызов бизнес-логики после ошибки."}],
    ["Что спрашивают и как усложнить","На интервью могут попросить написать middleware для логирования, авторизации или tracing, объяснить HandlerFunc, цепочку вызовов и передачу context. После базового упражнения добавь middleware для дедлайна и panic recovery с тестами. В production не выводи токены и персональные данные в логи, не меняй статус после начала ответа и не доверяй пользовательскому заголовку как гарантированно уникальному ID.",{"animation":"./media/http-middleware-6.gif","still":"./media/http-middleware-6-still.png","height":286,"alt":"заголовок есть → next. одни пробелы → отказ.","practice":"Проверь TrimSpace и контракт вызовов.","code":"if strings.TrimSpace(id) == \"\" { /* HTTP 400 */ }","production":"Для публичного API правила формата и генерации ID задаёт контракт."}]
  ]},
  {"id":"select-first","category":"Concurrency","section":"select: отмена, закрытие каналов и дедлайны","sources":["https://github.com/yakomisar/golang-questions","https://github.com/goavengers/go-interview/tree/master/docs/popular_tasks"],"theory":[
    ["Зачем это нужно","Сервис может ожидать событие из realtime-канала. Если клиент закрыл соединение или истёк deadline, ждать дальше бессмысленно. В рабочем коде операция должна возвращать результат или отменяться, иначе горутины будут накапливаться.",{"animation":"./media/select-first-1.gif","still":"./media/select-first-1-still.png","height":286,"alt":"запрос ожидает ID. отмена даёт выход из ожидания.","practice":"Жди сообщение и завершение контекста в select.","code":"case <-ctx.Done(): return \"\", ctx.Err()","production":"Отключившийся realtime-клиент освобождает ожидающий обработчик."}],
    ["Как работает select","select выбирает готовую коммуникацию из веток с отправкой/чтением. Если готовы несколько веток, выбор псевдослучаен; порядка или приоритета веток нет. Если ни одна ветка не готова, select блокируется, кроме случая default. С default ожидания нет, поэтому неправильный цикл с default может нагружать CPU.",{"animation":"./media/select-first-2.gif","still":"./media/select-first-2-still.png","height":286,"alt":"канал и ctx могут быть готовы. select выбирает одну готовую ветку.","practice":"После чтения проверь отмену по контракту задачи.","code":"if err := ctx.Err(); err != nil { return \"\", err }","production":"Так полученный ID не используют, если отмена уже видна."}],
    ["Nil и закрытые каналы","Отправка или чтение из nil channel блокируются, а в select такая ветка навсегда не готова. Отправка в закрытый канал паникует. Чтение из закрытого и исчерпанного канала возвращает zero value и ok=false. Поэтому нельзя определять закрытие только по значению: пустая строка или ноль могут быть допустимы.",{"animation":"./media/select-first-3.gif","still":"./media/select-first-3-still.png","height":286,"alt":"nil-канал выключает ветку. закрытый пустой канал даёт ok=false.","practice":"Проверяй второй результат чтения.","code":"case id, ok := <-ch:","production":"Отдельная ошибка канала отличает конец потока от валидного значения."}],
    ["Контекст и приоритет отмены","ctx.Done() закрывается по cancel или timeout; ctx.Err() возвращает context.Canceled или DeadlineExceeded. select не гарантирует, что ветка ctx.Done будет выбрана прежде готового чтения. Если контракт требует приоритет отмены при входе, проверяй ctx.Err() до select и после чтения.",{"animation":"./media/select-first-4.gif","still":"./media/select-first-4-still.png","height":286,"alt":"отмена уже произошла. предварительная проверка сразу вернёт ошибку.","practice":"Вызови ctx.Err перед select и после чтения.","code":"if err := ctx.Err(); err != nil { return \"\", err }","production":"Решение фиксирует поведение на точках проверки контекста."}],
    ["Инварианты решения","WaitMessage должен обработать три случая: ID получен, канал закрыт, контекст отменён. Не запускай дополнительную goroutine только ради ожидания: один select уже решает задачу. Учитывай nil channel — вместе с отменяемым контекстом функция всё равно должна завершиться при cancel.",{"animation":"./media/select-first-5.gif","still":"./media/select-first-5-still.png","height":286,"alt":"сообщение → id. отмена или закрытие → error.","practice":"Не заменяй причину отмены общей ошибкой.","code":"return \"\", ctx.Err()","production":"Handler может отдельно учитывать deadline и отмену клиента."}],
    ["Вопросы для интервью и практика","Могут дать код с select и попросить предсказать, заблокируется ли он, какую ветку выберет при двух готовых каналах, как проверить close, и почему default в бесконечном цикле опасен. После реализации добавь тесты на закрытый канал, pre-cancel, deadline и получение ID. Не делай тесты зависимыми от не гарантированного расписания goroutines.",{"animation":"./media/select-first-6.gif","still":"./media/select-first-6-still.png","height":286,"alt":"чтение готово одновременно с отменой. тест проверяет контракт kata.","practice":"Подготовь канал и заранее отмени контекст.","code":"got, err := WaitMessage(ctx, ch)","production":"Детерминированный тест помогает обходиться без произвольных sleep."}]
  ]},
  {"id":"event-validation","category":"Backend","section":"Go testing: таблицы, subtests и валидация","sources":["https://github.com/MedUnes/go-kata/tree/master/06-testing-quality/15-testing-parallel-fuzz-harness","https://github.com/goavengers/go-interview"],"theory":[
    ["Зачем тестировать простые функции","В API даже простая валидация решает, будет ли создано некорректное событие. Её легко сломать при рефакторинге: забыть пробелы, не учесть обязательный owner, начать мутировать вход. Поэтому мы тренируем не только написание функции, но и проектирование проверяемого контракта.",{"animation":"./media/event-validation-1.gif","still":"./media/event-validation-1-still.png","height":286,"alt":"API передал title и owner_id. валидация выполняется до записи.","practice":"Проверь оба обязательных поля после TrimSpace.","code":"if strings.TrimSpace(req.Title) == \"\" { return errors.New(\"title required\") }","production":"Отсекай неполные события до транзакции."}],
    ["Table-driven tests","Вместо нескольких почти одинаковых Test... создаём таблицу `{name, input, wantErr}`. Далее цикл и `t.Run(name, func(t *testing.T){...})`. Такой тест легко расширить новым кейсом. Тестовое имя должно объяснять сценарий: `empty title`, `spaces only`, `valid request`, а не просто номер.",{"animation":"./media/event-validation-2.gif","still":"./media/event-validation-2-still.png","height":286,"alt":"случаи: valid, пустой title. каждая строка проверяет один сценарий.","practice":"Используй таблицу с именем и ожидаемой ошибкой.","code":"t.Run(tc.name, func(t *testing.T) { _ = ValidateCreateEvent(tc.req) })","production":"Таблица упрощает добавление новых правил контракта."}],
    ["Стабильность и изоляция","Unit-тест не должен зависеть от продовой базы, времени системы или порядка map. Валидация обязана иметь одинаковый результат для одинакового запроса. Используй сравнения до и после вызова, если вход не должен меняться. Не проверяй строки ошибок без необходимости: лучше errors.Is/As или наличие ошибки.",{"animation":"./media/event-validation-3.gif","still":"./media/event-validation-3-still.png","height":286,"alt":"каждый тест создаёт свой запрос. результат воспроизводится.","practice":"Изолируй входы и проверяй ожидаемое поведение.","code":"err := ValidateCreateEvent(CreateEventRequest{Title:\"Sync\", OwnerID:\"42\"})","production":"Изолированные тесты не зависят от данных окружения."}],
    ["t.Parallel и гонки","Параллельные subtests имеют смысл, если состояние тестов независимо. Не копируй общий изменяемый указатель между кейсами без синхронизации. `go test -race` помогает найти обращения к общей памяти, но обнаруживает только реально выполненные конфликтующие пути.",{"animation":"./media/event-validation-4.gif","still":"./media/event-validation-4-still.png","height":286,"alt":"подтесты запущены параллельно. общий изменяемый объект вызовет гонку.","practice":"Давай каждому подтесту собственный запрос.","code":"req := tc.req","production":"Параллельные тесты полезны, когда у них нет общего изменяемого состояния."}],
    ["Где интеграционные тесты важнее unit","Unit-проверка ValidateCreateEvent не проверяет сохранение в PostgreSQL, транзакции или gRPC status codes. Для этого нужны отдельные интеграционные/контрактные тесты с настоящими зависимостями и управляемым окружением. Не выдавай тест одной функции за тест всего backend.",{"animation":"./media/event-validation-5.gif","still":"./media/event-validation-5-still.png","height":286,"alt":"unit проверяет правила. интеграционный проверяет handler и БД.","practice":"Проверь пустой owner_id без запуска БД.","code":"if strings.TrimSpace(req.OwnerID) == \"\" { return errors.New(\"owner required\") }","production":"Интеграционный тест дополнительно проверяет, что невалидный запрос не создаёт запись."}],
    ["Тренировка как в проде","Сначала выпиши случаи, затем реализуй ValidateCreateEvent, потом запусти `go test -run ^TestValidateCreateEvent$ -v`. Попробуй самостоятельно добавить новый кейс. На интервью часто спрашивают про table-driven tests, mocks, httptest, race, fuzz и как тестировать ошибки.",{"animation":"./media/event-validation-6.gif","still":"./media/event-validation-6-still.png","height":286,"alt":"title=\"  \" → ошибка. title=\"Sync\", owner_id=\"42\" → успех.","practice":"Проверь пробелы, пустого владельца и валидный запрос.","code":"if (err != nil) != tc.wantErr { t.Fatal(err) }","production":"Тест защищает входной контракт при изменении DTO."}]
  ]},
  {"id":"slice-detach","category":"Runtime","section":"Память: backing array, GC, escape analysis и benchmark","sources":["https://github.com/yakomisar/golang-questions","https://github.com/MedUnes/go-kata/tree/master/02-performance-allocation"],"theory":[
    ["Когда код держит лишнюю память","Сервис получает большой буфер с сетевыми данными и сохраняет только маленькую часть в кэше. Если сделать `small := large[:8]`, эти восемь байт всё ещё относятся к исходному backing array. Память может оставаться занятой даже тогда, когда остальные данные уже не нужны.",{"animation":"./media/slice-detach-1.gif","still":"./media/slice-detach-1-still.png","height":286,"alt":"большой буфер парсера. в кеш нужны только первые байты.","practice":"Верни независимую копию нужного диапазона.","code":"out := make([]byte, n); copy(out, data[:n])","production":"Короткое превью в кеше не удерживает большой входной буфер."}],
    ["Что именно хранит slice","Slice header концептуально содержит адрес элементов, длину и capacity. Срезирование не копирует данные: два среза могут указывать на один буфер. Присваивание `b := a` тоже копирует только header. `append` может переиспользовать буфер либо выделить другой — в зависимости от capacity.",{"animation":"./media/slice-detach-2.gif","still":"./media/slice-detach-2-still.png","height":286,"alt":"data[:n] меняет длину. backing array остаётся общим.","practice":"Ограничь n длиной входа перед копированием.","code":"if n > len(data) { n = len(data) }","production":"Разные представления буфера удобны только пока совпадает их время жизни."}],
    ["Почему GC не исправляет удержание","Сборщик мусора освобождает недостижимые объекты. Если маленький срез продолжает ссылаться на большой backing array, тот остаётся достижимым. Вызов GC не сделает массив недостижимым сам по себе. Решение — выделить отдельное хранилище для нужных байтов и перестать держать прежнюю ссылку.",{"animation":"./media/slice-detach-3.gif","still":"./media/slice-detach-3-still.png","height":286,"alt":"кеш хранит короткий slice. массив остаётся достижимым для GC.","practice":"Не сохраняй в кеше простой subslice.","code":"return out","production":"Разрыв ссылки помогает освободить исходный массив, если больше ссылок нет."}],
    ["Как сделать независимую копию","`out := make([]byte,n); copy(out,data[:n])` создаёт независимый массив с нужными байтами. Можно использовать `bytes.Clone`, но здесь важно отработать саму операцию. Подумай о контракте n<=0 и n>len(data). Тестируй независимость в обе стороны: мутация input не меняет output и наоборот.",{"animation":"./media/slice-detach-4.gif","still":"./media/slice-detach-4-still.png","height":286,"alt":"копируем n байт. изменение data не меняет out.","practice":"Выдели целевой буфер и вызови copy.","code":"copy(out, data[:n])","production":"Копирование на границе кеша отделяет данные от переиспользуемого буфера парсера."}],
    ["Escape analysis и реальные измерения","Сам факт создания среза не определяет стек или heap без учёта escape analysis и оптимизаций. `go build -gcflags='-m=2'` помогает понять решения компилятора. Для производительности используй `go test -bench . -benchmem` и pprof, если нужен разбор hot path. Не делай выводы по одному микробенчмарку без реалистичных входных данных.",{"animation":"./media/slice-detach-5.gif","still":"./media/slice-detach-5-still.png","height":286,"alt":"удержание видно в heap profile. копирование видно в allocs/op.","practice":"Сравни реализацию на больших входах.","code":"go test -bench . -benchmem","production":"Смотри живую память и объём аллокаций отдельно."}],
    ["Что спрашивают на интервью","Ожидают объяснение len/cap, append, aliasing, GC reachability, больших аллокаций и практических оптимизаций. Могут попросить написать код, который избегает удержания большого буфера, или диагностировать рост heap после кеширования маленьких строк и срезов.",{"animation":"./media/slice-detach-6.gif","still":"./media/slice-detach-6-still.png","height":286,"alt":"после вызова меняем data[0]. байт в результате прежний.","practice":"Проверь независимость результата и крайние n.","code":"got := DetachedPrefix(data, 2)","production":"Тест ловит регрессию при замене копии на простое срезание."}]
  ]},
  {"id":"idempotent-events","category":"Backend","section":"Kafka: повторная доставка, идемпотентность и гонки","sources":["https://github.com/goavengers/go-interview","https://github.com/MedUnes/go-kata"],"theory":[
    ["Почему сообщение приходит снова","Consumer может обработать сообщение, но упасть до подтверждения offset. После перезапуска та же запись приходит вновь. Это нормальный сценарий для at-least-once delivery. Бизнес-операция не должна дважды отправлять уведомление, списывать деньги или увеличивать счётчик.",{"animation":"./media/idempotent-events-1.gif","still":"./media/idempotent-events-1-still.png","height":286,"alt":"consumer получил event-42. после сбоя получает event-42 снова.","practice":"Используй ID как ключ обработки.","code":"applied := processor.Apply(\"event-42\")","production":"Повторная доставка возможна, если обработка завершилась до подтверждения."}],
    ["Идемпотентность как контракт","Обработка одного и того же event ID должна давать одинаковый итог при повторе. Для нашей учебной задачи возвращаем true только для первой обработки, false для повтора. Пустой ID считаем невалидным. Повтор должен оставаться повтором даже после другого нового сообщения.",{"animation":"./media/idempotent-events-2.gif","still":"./media/idempotent-events-2-still.png","height":286,"alt":"первый ID → эффект. тот же ID → состояние прежнее.","practice":"Возвращай false для уже виденного ID.","code":"if _, ok := p.seen[id]; ok { return false }","production":"Событие с тем же ID не должно повторно начислить бонус."}],
    ["Почему check-then-act опасен","Если две goroutines одновременно выполнят `if !seen[id] { seen[id]=...;count++ }`, обе могут решить, что ключ отсутствует. Это логическая гонка и при обычной map также возможна data race. Проверка, запись ID и изменение счётчика должны происходить в одной критической секции под mutex.",{"animation":"./media/idempotent-events-3.gif","still":"./media/idempotent-events-3-still.png","height":286,"alt":"два потока проверяют один ID. mutex защищает проверку и эффект.","practice":"Объедини проверку, запись и инкремент под одной блокировкой.","code":"p.mu.Lock(); defer p.mu.Unlock()","production":"Раздельные операции check и write открывают гонку между обработчиками."}],
    ["Преимущества zero value и ограничения","Можно сделать EventProcessor с нулевым значением, лениво создав map под mutex. В реальном процессе такая защита позволяет избежать дублей между несколькими goroutines. Но она не переживает рестарт: после перезапуска карта забывает все ID.",{"animation":"./media/idempotent-events-4.gif","still":"./media/idempotent-events-4-still.png","height":286,"alt":"пустой EventProcessor. первый Apply создаёт seen.","practice":"Инициализируй map под блокировкой.","code":"if p.seen == nil { p.seen = make(map[string]struct{}) }","production":"Zero value упрощает локальную модель; память процесса пропадает после рестарта."}],
    ["Что нужно в production","Для устойчивой идемпотентности используют уникальный ключ события и транзакцию, где запись о обработке и бизнес-изменение происходят атомарно, например в PostgreSQL с уникальным индексом. Другая задача — согласовать внешние side effects и outbox. Настройки Kafka сами по себе не сделают произвольную внешнюю БД exactly-once.",{"animation":"./media/idempotent-events-5.gif","still":"./media/idempotent-events-5-still.png","height":286,"alt":"процесс A и процесс B. оба используют один устойчивый ключ.","practice":"Различай учебную map и устойчивую запись о событии.","code":"p.seen[id] = struct{}{}","production":"Для эффекта в БД сохраняй маркер и изменение в одной транзакции, используя уникальный ключ."}],
    ["Проверка и интервью","Напиши `Apply` и `Count`, затем проверь серию дублей и конкурентную доставку одного ID через `go test -race`. На собеседовании объясни разницу delivery semantics и бизнес-идемпотентности, откуда берутся повторы и почему in-memory dedup — только учебный шаг.",{"animation":"./media/idempotent-events-6.gif","still":"./media/idempotent-events-6-still.png","height":286,"alt":"несколько Apply одного ID. Count остаётся 1.","practice":"Проверь повторные и конкурентные доставки.","code":"if p.Count() != 1 { t.Fatal(p.Count()) }","production":"Интеграционный тест может повторно доставить событие после перезапуска consumer."}]
  ]},
  {"id":"grpc-errors","category":"Backend","section":"gRPC: статусные коды, domain errors и контекст","sources":["https://github.com/goavengers/go-interview","https://grpc.io/docs/languages/go/basics/"],"theory":[
    ["Что происходит между сервисами","Клиент отправляет запрос по gRPC, серверный handler получает protobuf-сообщение, проверяет обязательные поля и вызывает service. Сервис не обязан знать, будет ли его результат возвращён через gRPC, HTTP или CLI. Поэтому доменная ошибка вроде ErrEventNotFound не должна смешиваться с codes.NotFound глубоко в слое хранения.",{"animation":"./media/grpc-errors-1.gif","still":"./media/grpc-errors-1-still.png","height":286,"alt":"service вернул доменную ошибку. handler переводит в RPC status.","practice":"Отдели классификацию от публичного сообщения.","code":"rpc := MapServiceError(err)","production":"Клиент использует код ответа, чтобы выбрать дальнейшее действие."}],
    ["Протокол и контракт","gRPC строится на HTTP/2 и обычно использует Protocol Buffers для сообщений. Protobuf-схема описывает поля и RPC. В Go protoc генерирует типы и интерфейсы, которые затем реализуются handler-ом. Unary RPC похож на вызов функции с request/response; streaming RPC позволяет передавать несколько сообщений.",{"animation":"./media/grpc-errors-2.gif","still":"./media/grpc-errors-2-still.png","height":286,"alt":"event не существует. клиент получает NotFound.","practice":"Задай код и стабильное публичное сообщение.","code":"return RPCStatus{Code: RPCNotFound, Message: \"event not found\"}","production":"Контракт статусов позволяет клиенту обработать отсутствующий ресурс."}],
    ["От error к статусу","Внутренний service может вернуть fmt.Errorf(\"load event: %w\", ErrEventNotFound). errors.Is на границе RPC распознает исходную причину. Handler переводит известную причину в status.Error(codes.NotFound,...), нарушение валидации — InvalidArgument, недоступную зависимость — иногда Unavailable, в зависимости от контракта. Неизвестные ошибки становятся Internal без утечки SQL или токенов.",{"animation":"./media/grpc-errors-3.gif","still":"./media/grpc-errors-3-still.png","height":286,"alt":"ошибка завёрнута через %w. errors.Is находит ErrEventNotFound.","practice":"Проверяй причину через errors.Is.","code":"case errors.Is(err, ErrEventNotFound):","production":"Внутренний слой добавляет контекст без изменения категории ошибки."}],
    ["Cancellation и deadline","У каждого RPC есть context. Если клиент отменил вызов, handler должен передать ctx в service/repository и уважать ctx.Err(). При отмене и дедлайне используют Canceled и DeadlineExceeded. Интерцепторы подходят для tracing, metrics, auth и единой обработки, но нельзя заменять ими доменную валидацию.",{"animation":"./media/grpc-errors-4.gif","still":"./media/grpc-errors-4-still.png","height":286,"alt":"ctx отменён → Canceled. истёк дедлайн → DeadlineExceeded.","practice":"Отдельно сопоставь ошибки контекста.","code":"case errors.Is(err, context.DeadlineExceeded):","production":"Метрики различают отключение клиента и исчерпание бюджета времени."}],
    ["Реальный код против учебной kata","В упражнении мы специально моделируем gRPC-коды собственным маленьким типом RPCStatus, чтобы проверить архитектурное правило без зависимости grpc-go. Это НЕ реализация настоящего протокола. В production нужны пакеты google.golang.org/grpc/codes и status, тесты реального transport handler, Protobuf-проверки и interceptors.",{"animation":"./media/grpc-errors-5.gif","still":"./media/grpc-errors-5-still.png","height":286,"alt":"внутренняя ошибка содержит детали БД. клиент получает Internal.","practice":"Используй короткий публичный текст для неизвестных ошибок.","code":"return RPCStatus{Code: RPCInternal, Message: \"internal error\"}","production":"В реальном gRPC handler формирует status.Error, а исходную причину пишет в серверный лог."}],
    ["Что спрашивают на собеседовании","Сравни HTTP JSON с gRPC, protobuf backward compatibility, unary и streaming, deadlines, interceptors, codes.NotFound/InvalidArgument/Internal, статусы unavailable и retry. Практика MapServiceError проверяет nil, %w и безопасный текст внутренних ошибок. Затем отдельно необходимо реализовать настоящий gRPC handler как следующую ступень.",{"animation":"./media/grpc-errors-6.gif","still":"./media/grpc-errors-6-still.png","height":286,"alt":"nil → OK; not found → NotFound. wrapped deadline → DeadlineExceeded.","practice":"Проверь таблицу кодов и отсутствие внутренних деталей.","code":"got := MapServiceError(fmt.Errorf(\"load: %w\", ErrEventNotFound))","production":"Контрактный тест закрепляет статус, который действительно получает клиент."}]
  ]},
  {"id":"pg-keyset","category":"Backend","section":"PostgreSQL: keyset pagination, индексы и SQL-инъекции","sources":["https://github.com/goavengers/go-interview/tree/master/docs/cache_and_db","https://www.postgresql.org/docs/current/queries-limit.html"],"theory":[
    ["Почему курсор важен в ListEvents","Когда пользователю нужно листать десятки тысяч событий, OFFSET с большими значениями может становиться дорогим. Между запросами новые строки появляются, старые удаляются, и позиционная пагинация может возвращать дубликаты. Keyset использует последний увиденный сортировочный ключ для получения следующей части.",{"animation":"./media/pg-keyset-1.gif","still":"./media/pg-keyset-1-still.png","height":286,"alt":"первая страница кончается на (T, B). следующая берёт строки меньше (T, B).","practice":"Передавай время и ID последней строки вместе.","code":"nextTime, nextID := last.CreatedAt, last.ID","production":"Так ListEvents продолжает обход отсортированного набора по ключу."}],
    ["Порядок должен быть полным","Одного created_at недостаточно: две записи могут иметь одинаковое время. Добавив id как уникальный tie-breaker, определяем порядок ORDER BY created_at DESC,id DESC. Следующий запрос ищет записи после курсора по тому же порядку. PostgreSQL позволяет сравнивать строки значений: (created_at,id) < ($2,$3), если типы и правила сортировки совместимы.",{"animation":"./media/pg-keyset-2.gif","still":"./media/pg-keyset-2-still.png","height":286,"alt":"у B и A одинаковое время. ID определяет, кто идёт первым.","practice":"Сортируй по created_at DESC, затем id DESC.","code":"ORDER BY created_at DESC, id DESC","production":"Стабильный tie-breaker предотвращает пропуски строк с одинаковым временем."}],
    ["Фильтр tenant и параметры","Для multi-tenant сервиса tenant_id должен применяться в каждом запросе, а не только на уровне API. Нельзя вставлять tenant_id или page_size как фрагменты SQL из внешнего ввода. Используем параметры $1, $2 и далее, а SQL остаётся заранее заданным. LIMIT ограничиваем серверным максимумом.",{"animation":"./media/pg-keyset-3.gif","still":"./media/pg-keyset-3-still.png","height":286,"alt":"tenant_id идёт отдельным аргументом. драйвер связывает значение с $1.","practice":"Параметризуй tenant, курсор и limit.","code":"args := []any{tenantID, before, beforeID, limit}","production":"Tenant-фильтр ограничивает выборку; tenant берут из авторизованного контекста."}],
    ["Индекс и план выполнения","Индекс, ориентированный на tenant_id, затем созданный сортировочный ключ, может ускорить поиск следующей страницы. Но фактический план зависит от селективности, типа полей, физической структуры таблицы и статистики. Проверяй EXPLAIN (ANALYZE, BUFFERS), а не обещай индексную скорость по одной записи SQL.",{"animation":"./media/pg-keyset-4.gif","still":"./media/pg-keyset-4-still.png","height":286,"alt":"индекс начинается с tenant_id. затем идут created_at и id.","practice":"Сопоставь индекс с WHERE и ORDER BY.","code":"CREATE INDEX ON events (tenant_id, created_at DESC, id DESC);","production":"Проверь реальный план через EXPLAIN (ANALYZE, BUFFERS)."}],
    ["Какие ограничения у курсора","Курсор должен соответствовать тому же фильтру и сортировке, что предыдущий запрос. Нужна валидация пары (timestamp,id). Конкретная схема в учебной kata предполагает непустой строковый ID и тип time.Time; в настоящем контракте обычно используются UUID, opaque page token, защита от подмены и политика последовательного чтения.",{"animation":"./media/pg-keyset-5.gif","still":"./media/pg-keyset-5-still.png","height":286,"alt":"только время без ID. курсор неполный → ошибка.","practice":"Принимай оба поля курсора или оба пустыми.","code":"if (beforeID == \"\") != before.IsZero() { return \"\", nil, errors.New(\"invalid cursor\") }","production":"Изменения ключей сортировки между страницами могут влиять на выдачу."}],
    ["Практика и интервью","Напиши BuildEventsPageQuery. Для первой страницы запрос содержит два аргумента, для продолжения — четыре. Проверь отсутствие интерполяции пользовательских строк и устойчивую сортировку. Объясни, как изменится результат при concurrent inserts и почему snapshot isolation или cursor не гарантируют одинаковый срез данных во всех сценариях.",{"animation":"./media/pg-keyset-6.gif","still":"./media/pg-keyset-6-still.png","height":286,"alt":"первая страница: tenant и limit. следующая: tenant, время, ID, limit.","practice":"Проверь SQL и порядок аргументов для обеих веток.","code":"query, args, err := BuildEventsPageQuery(tenantID, before, beforeID, 20)","production":"Интеграционный тест с одинаковыми timestamps проверяет стык страниц."}]
  ]},
  {"id":"kafka-ack","category":"Backend","section":"Kafka: offset, commit, at-least-once и сбои","sources":["https://github.com/goavengers/go-interview","https://kafka.apache.org/documentation/"],"theory":[
    ["Как работает доставка","Kafka хранит записи в партициях. Consumer group распределяет партиции по consumer-ам, и каждый consumer читает записи с определёнными offset. Само чтение не означает, что бизнес-операция над записью завершена. При сбое или rebalance записи могут быть обработаны повторно.",{"animation":"./media/kafka-ack-1.gif","still":"./media/kafka-ack-1-still.png","height":286,"alt":"получили сообщение. сбой до commit → возможна повторная доставка.","practice":"Сначала передай сообщение в handle.","code":"if err := handle(ctx, msg); err != nil { return err }","production":"В Kafka consumer может получить сообщение снова после рестарта или ребаланса."}],
    ["Подтверждение после эффекта","При ручном commit offset нужно сначала успешно обработать событие, а затем подтверждать прогресс чтения. Если подтвердить раньше, после сбоя запись может считаться пройденной, хотя побочный эффект не случился. Если эффект выполнен, но commit не состоялся, запись, скорее всего, будет получена снова.",{"animation":"./media/kafka-ack-2.gif","still":"./media/kafka-ack-2-still.png","height":286,"alt":"handle успешно записал эффект. теперь можно подтвердить позицию.","practice":"Вызывай commit только после успеха обработки.","code":"return commit(ctx)","production":"Раннее подтверждение может оставить сообщение необработанным после сбоя."}],
    ["Идемпотентность и внешняя БД","Повторная доставка нормальна при at-least-once. Для защиты от повторного бизнес-эффекта используют уникальный event ID и устойчивую отметку обработки. Если обработчик пишет в PostgreSQL, отметка дедупликации и бизнес-изменение должны происходить в одной транзакции, когда это возможно. Kafka transactions не делают внешние действия автоматически exactly-once.",{"animation":"./media/kafka-ack-3.gif","still":"./media/kafka-ack-3-still.png","height":286,"alt":"БД зафиксировала эффект. commit Kafka упал → повтор.","practice":"Принимай возможность повторной обработки.","code":"err := HandleAndCommit(ctx, msg, handle, commit)","production":"Защити изменение БД уникальным ID события и атомарной записью маркера."}],
    ["Ошибки и cancellation","Handler может вернуть ошибку. Тогда offset не подтверждаем и решение о retry, pause или dead-letter queue должно определяться контрактом consumer. Контекст отмены, deadlines и shutdown важны при остановке. Не вызывай commit после ошибки или уже отменённого контекста.",{"animation":"./media/kafka-ack-4.gif","still":"./media/kafka-ack-4-still.png","height":286,"alt":"handle завершился. ctx отменён → commit пропускаем.","practice":"Проверяй контекст до handle и перед commit.","code":"if err := ctx.Err(); err != nil { return err }","production":"При остановке consumer учитывай, что незафиксированная позиция может привести к повтору."}],
    ["Почему эта задача не настоящий consumer","В упражнении мы реализуем последовательность callback-ов handle и commit, а не Kafka-клиент. Для реального кода нужны partition ownership, учёт offset при конкурентной обработке, rebalance hooks, batch и retry policies. Нельзя коммитить offset N, пока запись с меньшим offset той же partition ещё не завершилась.",{"animation":"./media/kafka-ack-5.gif","still":"./media/kafka-ack-5-still.png","height":286,"alt":"kata вызывает один callback commit. реальный commit относится к partition.","practice":"Проверь порядок вызовов на одном сообщении.","code":"handle(ctx, msg); // после успеха и проверки ctx вызывается commit","production":"При параллельной обработке не подтверждай offset поверх незавершённых сообщений той же partition."}],
    ["Что спрашивают и как тренировать","Различия at-most-once/at-least-once/exactly-once, consumer group, commit, rebalance, idempotent producer и обработка дубликатов. Напиши HandleAndCommit с тестами: успех, ошибка handle, ошибка commit, pre-cancel и порядок вызовов. Затем усложни до batched consumer, в котором подтверждается только непрерывный обработанный диапазон offsets.",{"animation":"./media/kafka-ack-6.gif","still":"./media/kafka-ack-6-still.png","height":286,"alt":"fake handle вернул ошибку. fake commit не вызван.","practice":"Запиши порядок вызовов в тесте.","code":"if commitCalls != 0 { t.Fatal(commitCalls) }","production":"Интеграционный тест может проверить повторную доставку при сбое между эффектом и commit."}]
  ]},
  {"id":"perf-builder","category":"Runtime","section":"Производительность: strings.Builder, аллокации и бенчмарки","sources":["https://github.com/MedUnes/go-kata/tree/master/02-performance-allocation","https://github.com/yakomisar/golang-questions"],"theory":[
    ["Зачем профилировать Go","Backend расходует CPU и память в обработчиках запросов, сериализации и логировании. Внешне простая операция может выполняться тысячи раз за секунду. В таких местах лишние аллокации увеличивают нагрузку на GC. Но сначала нужна метрика latency/throughput/allocs, иначе оптимизировать можно не тот участок.",{"animation":"./media/perf-builder-1.gif","still":"./media/perf-builder-1-still.png","height":286,"alt":"лог собирается на каждом событии. лишние аллокации растут с нагрузкой.","practice":"Собери строку из частей через Builder.","code":"var b strings.Builder","production":"Оптимизируй часто выполняемый путь после измерения."}],
    ["Как строятся строки","string в Go неизменяем: операция объединения строк создаёт новую строку семантически. В цикле `result += part` может повторно копироваться всё уже накопленное содержимое. Компилятор иногда оптимизирует конкатенацию, поэтому нельзя без benchmark утверждать, что она всегда квадратична именно в конкретном коде.",{"animation":"./media/perf-builder-2.gif","still":"./media/perf-builder-2-still.png","height":286,"alt":"строка: \"a\" → \"a/b\" → \"a/b/c\". при конкатенации копируется префикс.","practice":"Записывай части в общий буфер.","code":"b.WriteString(part)","production":"Это уменьшает копирование при сборке длинного диагностического поля."}],
    ["strings.Builder","Builder хранит внутренний буфер для последовательного добавления фрагментов. WriteString и WriteByte позволяют постепенно строить результат. Grow может заранее зарезервировать нужную capacity и сократить перераспределения. После начала использования нельзя копировать непустой Builder по значению; при необходимости используй Reset.",{"animation":"./media/perf-builder-3.gif","still":"./media/perf-builder-3-still.png","height":286,"alt":"считаем длину частей и разделителей. Grow резервирует место.","practice":"Добавляй разделитель только перед второй и последующими частями.","code":"if i > 0 { b.WriteByte('|') }","production":"Предварительный размер полезен, если точную длину посчитать дёшево."}],
    ["Benchmark и benchmem","Тестовая функция `BenchmarkX(b *testing.B)` многократно выполняет код и измеряет операцию. Запусти `go test -run '^$' -bench BenchmarkBuildLogLine -benchmem`. Обрати внимание на ns/op, B/op и allocs/op; сравни с альтернативным вариантом, используя одинаковые входные данные и избегая устранения работы компилятором.",{"animation":"./media/perf-builder-4.gif","still":"./media/perf-builder-4-still.png","height":286,"alt":"запускаем два benchmark. сравниваем ns/op и allocs/op.","practice":"Используй одинаковые входы для сравнения.","code":"go test -bench . -benchmem","production":"Сравни на типичных и крупных сообщениях."}],
    ["Escape analysis, GC и pprof","`go build -gcflags='-m=2'` показывает решения компилятора, связанные с inlining и escape analysis. Heap/allocs profile помогает найти реальные аллокации в работающем приложении. GOGC и GOMEMLIMIT управляют политикой GC, но не заменяют устранение ненужных копий, чрезмерного хранения объектов и корректного lifecycle.",{"animation":"./media/perf-builder-5.gif","still":"./media/perf-builder-5-still.png","height":286,"alt":"benchmark показал аллокации. heap profile показывает источники.","practice":"Сравни профили реализаций на одинаковой нагрузке.","code":"go test -bench . -memprofile mem.out","production":"В профиле разделяй объём выделений и живую память."}],
    ["Как отвечать на собеседовании","Расскажи, как измеряешь узкое место, чем отличаются heap и allocs profiles, когда применяешь pprof и race detector, почему benchmark нужен до и после оптимизации. Практика BuildLogLine проверяет корректную обработку пустых полей, разделителей и использование Builder; затем сравни показатели с конкатенацией в цикле.",{"animation":"./media/perf-builder-6.gif","still":"./media/perf-builder-6-still.png","height":286,"alt":"пустой вход → пустая строка. [\"a\",\"b\"] → \"a|b\".","practice":"Проверь выход до оптимизации и после неё.","code":"got := BuildLogLine([]string{\"a\", \"b\"})","production":"Оптимизация не должна менять формат, который разбирают потребители логов."}]
  ]},
  {"id":"generic-unique","category":"Go Core","section":"Generics: type parameters, comparable и безопасный Set","sources":["https://github.com/exercism/go/tree/main/exercises/concept/generic-set","https://github.com/yakomisar/golang-questions"],"theory":[
    ["Почему generic-код нужен backend","В двух сервисах есть почти одинаковая дедупликация: один обрабатывает строковые ID, другой — числовые. Копировать целую функцию под каждый тип не хочется, а []interface{} заставляет терять статические гарантии и заниматься приведением типов. Дженерики позволяют сохранить алгоритм, подставляя конкретный тип при компиляции.",{"animation":"./media/generic-unique-1.gif","still":"./media/generic-unique-1-still.png","height":286,"alt":"userID: строка, eventID: число. один алгоритм работает для обоих.","practice":"Объяви параметр типа T для входа и выхода.","code":"func UniqueValues[T comparable](values []T) []T","production":"Общий helper полезен при одинаковом контракте дедупликации."}],
    ["Type parameters и constraints","Синтаксис `func UniqueValues[T comparable](values []T) []T` вводит параметр типа T. `comparable` означает допустимость операций == и != для набора типов, что важно для map[T]struct{}. Constraint ограничивает, какие типы можно подставлять: `[]int` как значение slice не сравним и потому не подходит. Компилятор сигнализирует об ошибке на этапе сборки.",{"animation":"./media/generic-unique-2.gif","still":"./media/generic-unique-2-still.png","height":286,"alt":"map использует T как ключ. constraint comparable разрешает сравнение.","practice":"Ограничи T типами, допустимыми в позиции ключа.","code":"seen := make(map[T]struct{}, len(values))","production":"Компилятор проверит типы на местах вызова."}],
    ["Сравнение с интерфейсами","Обычный interface описывает поведение через набор методов; generic constraint описывает допустимые типы/операции. Вместо повторного runtime type assertion можно написать код, в котором компилятор знает T. Но generics не заменяют interfaces повсюду: интерфейсы удобны для абстракции зависимостей (repository, HTTP client), а generics — для обобщённых алгоритмов и контейнеров.",{"animation":"./media/generic-unique-3.gif","still":"./media/generic-unique-3-still.png","height":286,"alt":"вход []string → выход []string. вход []int → выход []int.","practice":"Сохрани конкретный тип результата.","code":"out := make([]T, 0, len(values))","production":"Типизированный helper избавляет вызывающий код от приведения элементов."}],
    ["Comparable и неожиданные случаи","Типы с несравнимыми полями нельзя использовать ключами map. Для generic-примера с int и string сравнение однозначно. С интерфейсами, допускаемыми comparable, бывают нюансы: динамическое значение может оказаться несравнимым и вызвать panic при сравнении. Не надо обещать, что comparable избавляет от всех возможных runtime-ошибок в любых комбинациях типов.",{"animation":"./media/generic-unique-4.gif","still":"./media/generic-unique-4-still.png","height":286,"alt":"int — сравнимый тип. []byte — несравнимый тип.","practice":"Проверь поведение с определённым типом ID.","code":"type UserID string","production":"С interface-типом несравнимое динамическое значение всё ещё может вызвать panic."}],
    ["Порядок и сложность","Для подсчёта уникальных значений храни `seen := make(map[T]struct{})`, а порядок первых появлений — в `out []T`. Сам map не гарантирует последовательность ключей. Ожидаемая сложность O(n) по времени и O(k) по памяти при k уникальных элементах. На собеседовании может потребоваться объяснить семантику append и общий backing array.",{"animation":"./media/generic-unique-5.gif","still":"./media/generic-unique-5-still.png","height":286,"alt":"вход: 3, 1, 3, 2. выход: 3, 1, 2.","practice":"Добавляй значение при первом появлении.","code":"out = append(out, v)","production":"Generic helper сохраняет тот же порядок, что специализированная версия."}],
    ["Как тренироваться","Сначала реши задачу отдельно для []int, затем обобщи до T comparable. Напиши два теста с разными типами и сравни интерфейсный подход с generic. Для продакшена важны понятный API, хорошее название типа и отсутствие неоправданной абстракции. Дженерики не должны превращать простой код в тяжёлую универсальную библиотеку.",{"animation":"./media/generic-unique-6.gif","still":"./media/generic-unique-6-still.png","height":286,"alt":"два вызова с разными типами. одинаковый контракт порядка.","practice":"Прогони строковые и числовые случаи.","code":"got := UniqueValues([]int{3, 1, 3})","production":"Добавь проверку на типы ID, которые действительно использует сервис."}]
  ]},
  {"id":"gc-cache","category":"Runtime","section":"GC: достижимость объектов, TTL eviction, GOGC и GOMEMLIMIT","sources":["https://github.com/yakomisar/golang-questions","https://go.dev/doc/gc-guide"],"theory":[
    ["Реальная ситуация","У мессенджера есть in-memory cache по ключу пользователя или сообщения. Записи имеют срок жизни, однако при отсутствии уборки map постепенно увеличивается. Разработчик видит рост heap и пытается вызвать runtime.GC, но записи продолжают занимать память. Проблема не в том, что сборщик «не умеет», — для него эти объекты всё ещё достижимы.",{"animation":"./media/gc-cache-1.gif","still":"./media/gc-cache-1-still.png","height":286,"alt":"в кеше записи с истёкшим TTL. map всё ещё держит значения.","practice":"Удаляй истёкшие записи при проходе.","code":"delete(entries, k)","production":"Eviction ограничивает объём записей, которые держит кеш."}],
    ["Что отслеживает GC","Go использует concurrent tracing garbage collector: он просматривает достижимые объекты, стартуя с корней, и освобождает недостижимое. Если ключ и значение находятся в доступной map, сборщик видит ссылки на них и сохраняет. TTL — прикладное поле, не известное сборщику; оно не делает данные недостижимыми. Есть накладные расходы и короткие stop-the-world фазы, однако большая часть работы конкурентная.",{"animation":"./media/gc-cache-2.gif","still":"./media/gc-cache-2-still.png","height":286,"alt":"map достижима из сервиса. значение достижимо через ключ.","practice":"Удали ссылку из map, когда значение больше не нужно.","code":"delete(entries, k)","production":"GC может освободить значение после исчезновения всех ссылок на него."}],
    ["GOGC, GOMEMLIMIT и производительность","GOGC влияет на целевой рост heap между циклами: снижение GOGC обычно уменьшает объём живой/неочищенной памяти ценой большей работы GC. GOMEMLIMIT задаёт мягкий общий лимит памяти, учитываемой runtime, и может побуждать GC работать чаще. Это инструменты настройки компромиссов, но они не удаляют живые записи map. Обещать, что GOMEMLIMIT всегда удержит RSS строго ниже числа, нельзя.",{"animation":"./media/gc-cache-3.gif","still":"./media/gc-cache-3-still.png","height":286,"alt":"живые записи остаются достижимыми. настройки GC меняют режим сборки.","practice":"Исправь удержание удалением истёкших ключей.","code":"removed := EvictExpired(entries, now)","production":"GOMEMLIMIT и GOGC влияют на частоту сборки, но TTL определяет код кеша."}],
    ["Eviction и время","Если `ExpiresAt <= now`, запись должна исчезнуть из структуры. Удаление из map делается через delete; это допустимо во время range по map в Go. После удаления объект может стать недостижимым, если на него больше никто не ссылается; фактическое освобождение зависит от GC и оставшихся ссылок. Удаление элемента не гарантирует немедленное уменьшение RSS ОС.",{"animation":"./media/gc-cache-4.gif","still":"./media/gc-cache-4-still.png","height":286,"alt":"ExpiresAt=now. запись уже истекла.","practice":"Удали записи с временем раньше или ровно now.","code":"if !e.ExpiresAt.After(now) { delete(entries, k); removed++ }","production":"Передавай снимок времени на весь проход, чтобы граница была одинаковой."}],
    ["Как измерять","В тесте время нужно передавать явно, чтобы не ждать реальные секунды. В проде добавляют периодический sweeper, max entries/weight и наблюдаемость по размеру cache. Используют runtime/metrics, pprof heap/allocs и метрики нагрузки; отличают живую память, аллокации и удержание backing arrays. Анализируй профили до изменения GOGC.",{"animation":"./media/gc-cache-5.gif","still":"./media/gc-cache-5-still.png","height":286,"alt":"замеряем до eviction. сравниваем число ключей и живую память.","practice":"Возвращай число удалённых записей.","code":"return removed","production":"Метрика удаления и heap profile показывают разные стороны работы кеша."}],
    ["Чего ждут на интервью","Вопросы: mark/sweep, tri-color marking в общих чертах, write barrier, stack и heap, причины GC pauses, GOGC и memory limit, почему не освобождается память. Умей объяснить, что логическая истёкшая запись продолжает жить в map. Практика EvictExpired проверяет границу TTL, удаление во время range и deterministic tests.",{"animation":"./media/gc-cache-6.gif","still":"./media/gc-cache-6-still.png","height":286,"alt":"час фиксирован в тесте. граница TTL проверяется без sleep.","practice":"Передай заданное now и проверь результат.","code":"removed := EvictExpired(entries, time.Unix(100, 0))","production":"Проверка времени защищает от пограничных ошибок при регулярной очистке."}]
  ]},
  {"id":"scheduler-fanout","category":"Runtime","section":"GMP scheduler: goroutines, P/M/G и ограниченный fan-out","sources":["https://github.com/yakomisar/golang-questions","https://github.com/MedUnes/go-kata/tree/master/01-context-cancellation-concurrency/07-rate-limited-fanout"],"theory":[
    ["Почему goroutine не равна потоку","Внешний API получил запрос на объединение данных из десяти сервисов. Для каждого запроса можно запустить goroutine, но десять тысяч одновременных запросов перегрузят зависимости. Планировщик Go позволяет запускать большое количество goroutines относительно лёгкими средствами, однако он не ограничивает число исходящих сетевых операций ради твоего сервиса.",{"animation":"./media/scheduler-fanout-1.gif","still":"./media/scheduler-fanout-1-still.png","height":286,"alt":"несколько вызовов ждут сеть. runtime переключает горутины.","practice":"Ограничивай число работающих job по контракту.","code":"err := RunLimited(ctx, 2, jobs)","production":"Так fan-out не перегружает зависимость."}],
    ["Модель G-M-P","G — goroutine с собственным стеком и состоянием; M — OS thread, на котором может выполняться Go-код; P — логический ресурс планировщика с локальной очередью и необходимым контекстом для исполнения G. M выполняет Go-код, имея P. При блокирующих системных вызовах и ожидании сети runtime может переключать работу так, чтобы продолжать выполнение других горутин.",{"animation":"./media/scheduler-fanout-2.gif","still":"./media/scheduler-fanout-2-still.png","height":286,"alt":"G — горутина, M — поток. P даёт ресурсы для исполнения Go-кода.","practice":"Отдели планирование runtime от семафора задачи.","code":"sem := make(chan struct{}, limit)","production":"Лимит приложения управляет нагрузкой независимо от планировщика."}],
    ["GOMAXPROCS и concurrency","GOMAXPROCS управляет числом P, которые могут одновременно выполнять Go-код, но не количеством goroutines в программе и не количеством I/O запросов. Современные версии Go учитывают ограничения среды при выборе значения по умолчанию; детали зависят от релиза. Само увеличение GOMAXPROCS не исправляет перегрузку базы или API.",{"animation":"./media/scheduler-fanout-3.gif","still":"./media/scheduler-fanout-3-still.png","height":286,"alt":"GOMAXPROCS задаёт P. лимит job задаёт число работ в полёте.","practice":"Выбери limit по ресурсу, к которому обращаются задания.","code":"err := RunLimited(ctx, limit, jobs)","production":"Даже на одном P может быть много запросов, ожидающих сеть."}],
    ["Семафор через buffered channel","Можно создать `sem := make(chan struct{},limit)`; запись в него занимает слот, чтение освобождает. Если одновременно заняты limit слотов, следующая отправка ждёт освобождения. Сочетай захват слота с `ctx.Done()`, иначе запрос зависнет на отмене. Для контроля ошибок применяй sync.Once или другой механизм, а по окончании ожидай WaitGroup.",{"animation":"./media/scheduler-fanout-4.gif","still":"./media/scheduler-fanout-4-still.png","height":286,"alt":"свободный слот → кладём токен. работа завершилась → вынимаем токен.","practice":"Захватывай слот до запуска горутины.","code":"defer func() { <-sem }()","production":"Ограничение до запуска сокращает число горутин, которые только ждут своей очереди."}],
    ["Fail-fast и жизненный цикл","При первой ошибке внешнего вызова общий контекст нужно отменить, чтобы больше не начинать новые работы и оповестить уже запущенные. Сам context не может насильно прервать fn: функция должна сотрудничать. Важно дождаться всех goroutines перед возвратом. Ошибки и ожидания не должны запускать unbounded goroutines за спиной пользователя.",{"animation":"./media/scheduler-fanout-5.gif","still":"./media/scheduler-fanout-5-still.png","height":286,"alt":"первая ошибка → отмена. координатор ждёт начатые работы.","practice":"Передай дочерний ctx и дождись wg.Wait.","code":"once.Do(func() { first = err; cancel() })","production":"Зависимость должна учитывать контекст, чтобы fail-fast быстро завершился."}],
    ["Проверка навыка","Нарисуй схему: producer берёт семафор → стартует goroutine → освобождает слот → WaitGroup. Напиши RunLimited, затем в тесте через atomic измерь максимальную конкурентность. Добавь ошибку из callback и pre-cancel. На собеседовании объясни, чем worker pool отличается от ограниченного fan-out и что runtime scheduler не заменяет rate limiting.",{"animation":"./media/scheduler-fanout-6.gif","still":"./media/scheduler-fanout-6-still.png","height":286,"alt":"тест блокирует две job. третья ждёт свободный слот.","practice":"Проверь максимум параллельных вызовов и завершение.","code":"wg.Wait()","production":"Каналы-сигналы помогают проверить лимит без ожиданий наугад."}]
  ]},
  {"id":"channel-pipeline","category":"Concurrency","section":"Channels: pipeline, backpressure, cancellation и ownership","sources":["https://github.com/goavengers/go-interview/tree/master/docs/popular_tasks","https://github.com/MedUnes/go-kata/tree/master/01-context-cancellation-concurrency/17-context-aware-channel-sender"],"theory":[
    ["Как появляется pipeline","Есть поток сообщений, над которыми нужно выполнить последовательные шаги: декодировать, проверить, преобразовать, отправить. Вместо одной большой функции можно организовать стадии, связанные каналами. Каждая стадия получает значения из входного канала и передаёт результаты в выходной; так можно строить потоковую обработку.",{"animation":"./media/channel-pipeline-1.gif","still":"./media/channel-pipeline-1-still.png","height":286,"alt":"производитель подаёт 2 и 3. стадия выдаёт 4 и 9.","practice":"Преобразуй каждый вход в отдельной горутине.","code":"case out <- v * v:","production":"Аналогичная стадия может нормализовать элементы потока."}],
    ["Чтение и закрытие каналов","Для `in <-chan int` допускается только чтение. Стадия не должна закрывать вход: он принадлежит producer-у. Выходной канал создаёт сама стадия, поэтому она и закрывает его, когда больше ничего не отправит. Чтение из закрытого канала возвращает zero value и `ok=false`, а range заканчивается после исчерпания буфера.",{"animation":"./media/channel-pipeline-2.gif","still":"./media/channel-pipeline-2-still.png","height":286,"alt":"вход закрывается после данных. стадия закрывает собственный выход.","practice":"Проверяй ok при чтении и закрывай out через defer.","code":"defer close(out)","production":"Downstream завершит range, когда источник закончится."}],
    ["Backpressure на отправке","Если получатель медленный, отправка в unbuffered out блокируется до чтения. Это полезный естественный backpressure, но при уходе клиента стадия может зависнуть навечно. Отправка должна происходить через `select { case out <- value: case <-ctx.Done(): return }`, чтобы отмена прерывала ожидание.",{"animation":"./media/channel-pipeline-3.gif","still":"./media/channel-pipeline-3-still.png","height":286,"alt":"downstream не читает. отправка ждёт, пока чтение или отмена готовы.","practice":"Включи ctx.Done в select отправки.","code":"select { case out <- v*v: case <-ctx.Done(): return }","production":"При отключении клиента стадия перестаёт удерживать горутину."}],
    ["Отмена на чтении","Если входной канал никогда не закроется, простой `for v := range in` будет ждать бесконечно, даже после cancel. Поэтому на чтении также нужен select с ctx.Done. Нулевые каналы в select блокируют свою ветку; при отменяемом контексте можно всё-таки завершиться. `select` не гарантирует, какая из одновременно готовых веток выберется.",{"animation":"./media/channel-pipeline-4.gif","still":"./media/channel-pipeline-4-still.png","height":286,"alt":"пустой вход блокирует чтение. ctx.Done прерывает ожидание.","practice":"Проверяй отмену в select чтения.","code":"case <-ctx.Done(): return","production":"Дедлайн останавливает pipeline, даже когда upstream молчит."}],
    ["Сохранение порядка и fan-out","Если одна goroutine читает вход и последовательно посылает квадраты, порядок значений сохраняется. Если несколько workers обрабатывают одновременно, порядок завершения может измениться. При требованиях к порядку нужны индексы и reorder stage либо иной подход. Не путай fan-in (объединение) с pipeline (последовательные стадии).",{"animation":"./media/channel-pipeline-5.gif","still":"./media/channel-pipeline-5-still.png","height":286,"alt":"одна стадия: 2 → 4, 3 → 9. несколько worker могут завершиться в другом порядке.","practice":"Сохрани последовательную обработку, если требуется порядок.","code":"for value := range out { got = append(got, value) }","production":"При параллельной обработке нужен отдельный механизм восстановления порядка."}],
    ["Тесты и реальная эксплуатация","Нужно проверить вход 1,2,3, закрытие, отмену при заблокированной отправке, прекращение без goroutine leak. Тестируй завершение с таймаутом, а не с произвольными sleep. На интервью объясни, кто закрывает out, что делать с не читающим downstream и как отмена передаётся вдоль pipeline.",{"animation":"./media/channel-pipeline-6.gif","still":"./media/channel-pipeline-6-still.png","height":286,"alt":"закрытый вход → закрытый out. заблокированная отправка + cancel → выход.","practice":"Проверь нормальное завершение и отмену.","code":"out := SquarePipeline(ctx, in)","production":"Тест с дедлайном выявляет утечку стадии при остановке."}]
  ]},
  {"id":"pg-transaction","category":"Backend","section":"PostgreSQL: транзакции, MVCC, rollback и согласованность","sources":["https://github.com/goavengers/go-interview/tree/master/docs/cache_and_db","https://www.postgresql.org/docs/current/tutorial-transactions.html"],"theory":[
    ["Что должна гарантировать транзакция","При создании события calendar-service записывает event и attendees. Если event сохранился, а attendees упали, система может оказаться в неконсистентном состоянии. Транзакция объединяет эти операции: либо фиксируем весь набор изменений, либо откатываем при ошибке. Но разные внешние системы и Kafka не становятся частью одной PostgreSQL-транзакции автоматически.",{"animation":"./media/pg-transaction-1.gif","still":"./media/pg-transaction-1-still.png","height":286,"alt":"INSERT event успешен. INSERT attendees упал → rollback обоих.","practice":"Выполняй обе записи через переданный tx.","code":"err := work(ctx, tx)","production":"Событие и список участников сохраняются как одна операция."}],
    ["ACID и MVCC","Atomicity означает «всё или ничего» для изменений транзакции. Consistency относится к соблюдению ограничений, Isolation — к взаимодействию параллельных транзакций, Durability — к сохранению зафиксированного результата. PostgreSQL использует MVCC, поддерживая версии строк и snapshot visibility, благодаря чему чтения и записи могут взаимодействовать эффективнее, хотя блокировки и конфликты остаются.",{"animation":"./media/pg-transaction-2.gif","still":"./media/pg-transaction-2-still.png","height":286,"alt":"T1 меняет строки. T2 видит версии по своему snapshot.","practice":"Держи связанный набор изменений внутри транзакции.","code":"tx, err := db.BeginTx(ctx)","production":"MVCC позволяет читателям видеть согласованные версии согласно уровню изоляции."}],
    ["BeginTx, Commit, Rollback в Go","Типичный код через database/sql вызывает BeginTx(ctx,opts), затем `defer tx.Rollback()` на случай ошибки, выполняет запросы через tx и в конце вызывает tx.Commit(). После успешного Commit отложенный Rollback обычно возвращает sql.ErrTxDone и не меняет результат; это нормальный распространённый шаблон. Ошибка commit должна быть возвращена и обработана — вызывающий не может считать её успешной записью.",{"animation":"./media/pg-transaction-3.gif","still":"./media/pg-transaction-3-still.png","height":286,"alt":"BeginTx → work → Commit. ошибка work → Rollback.","practice":"Отложи Rollback сразу после успешного BeginTx.","code":"defer tx.Rollback()","production":"Единый путь очистки помогает на каждом раннем выходе."}],
    ["Context и ошибка транзакции","Передавай context в BeginTx и запросы, чтобы учитывать cancel/deadline. Если рабочая функция вернула ошибку, нельзя вызывать Commit. Не забывай, что утрата соединения во время Commit может оставить результат неоднозначным для клиента; идемпотентность и корректный retry зависят от контракта операции.",{"animation":"./media/pg-transaction-4.gif","still":"./media/pg-transaction-4-still.png","height":286,"alt":"work закончилось. ctx отменён → не начинаем commit.","practice":"Проверь ctx.Err перед фиксацией, верни ошибку commit.","code":"return tx.Commit()","production":"При обрыве связи результат commit иногда требует отдельного выяснения через контракт операции."}],
    ["Уровни изоляции и блокировки","Read Committed — распространённый уровень по умолчанию в PostgreSQL, где каждый оператор видит подходящий snapshot. Repeatable Read и Serializable дают более сильные гарантии, но возможны ошибки сериализации и необходимость повторить всю транзакцию. Deadlocks возникают при конфликтующем порядке захвата блокировок. Запрашивать строгую изоляцию без понимания цены опасно.",{"animation":"./media/pg-transaction-5.gif","still":"./media/pg-transaction-5-still.png","height":286,"alt":"T1 блокирует строку. T2 ждёт или получает ошибку.","practice":"Учебный helper сохраняет причину ошибки вызывающему коду.","code":"if err := work(ctx, tx); err != nil { return err }","production":"При повторе serialization failure повторяют всю транзакцию, учитывая внешние эффекты."}],
    ["Практика и собеседование","Сначала реализуй `WithinTx` поверх маленьких интерфейсов, а затем сделай fake для записи порядка Begin → work → Commit или Rollback. Это unit-тест orchestration, не интеграционный тест PostgreSQL. Следующим уровнем нужны `testcontainers` или Docker с настоящей Postgres, проверка UNIQUE, isolation и rollback при SQL-ошибке.",{"animation":"./media/pg-transaction-6.gif","still":"./media/pg-transaction-6-still.png","height":286,"alt":"fake фиксирует Begin и work. при ошибке записывает Rollback.","practice":"Проверь ветки успеха, ошибки callback и ошибки Commit.","code":"err := WithinTx(ctx, fakeDB, work)","production":"Проверка на реальном PostgreSQL подтверждает атомарность записей."}]
  ]}
];
